INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0064', 'Barbell One Arm Bent Over Row', 'back', 'upper back', '["biceps","forearms"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.","Bend forward at the hips, keeping your back straight and your head in a neutral position.","Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, घुटने थोड़े मुड़े हुए हों और ओवरहैंड ग्रिप का उपयोग करके एक हाथ से बारबेल को पकड़ें।","अपनी पीठ को सीधा रखते हुए और अपने सिर को तटस्थ स्थिति में रखते हुए, कूल्हों के बल आगे की ओर झुकें।","अपनी कोहनी को अपने शरीर के पास रखते हुए और अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बारबेल को अपनी छाती की ओर खींचें।","नियंत्रित तरीके से बारबेल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0065', 'Barbell One Arm Floor Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'barbell', 'strength', NULL, '["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest.","Slowly lower the barbell towards your chest, keeping your elbow close to your body.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने घुटनों को मोड़कर और पैरों को जमीन पर सपाट रखते हुए फर्श पर अपनी पीठ के बल लेट जाएं।","एक हाथ से बारबेल को पकड़ें, हथेली ऊपर की ओर रखें और अपने हाथ को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी कोहनी को अपने शरीर के करीब रखते हुए बारबेल को धीरे-धीरे अपनी छाती की ओर नीचे लाएं।","नीचे एक क्षण के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0066', 'Barbell One Arm Side Deadlift', 'upper legs', 'glutes', '["hamstrings","quadriceps","lower back"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.","Keep your back straight and your core engaged.","Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.","Lower the barbell as far as you can while maintaining good form.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में बारबेल को ओवरहैंड पकड़ के साथ पकड़ लें।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","कूल्हों पर झुकें और बारबेल को अपने पैर के बाहर की ओर नीचे करें, अपनी बांह सीधी रखें और अपनी छाती ऊपर रखें।","अच्छी फॉर्म बनाए रखते हुए बारबेल को जितना हो सके उतना नीचे करें।","एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0067', 'Barbell One Arm Snatch', 'shoulders', 'delts', '["traps","forearms","core"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Explosively extend your hips, knees, and ankles, driving the barbell upwards.","As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body.","Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर की ओर हों।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपने घुटनों को मोड़ें और अपने कूल्हों को स्क्वाट स्थिति में लाएं, अपनी पीठ सीधी और छाती ऊपर रखें।","अपने कूल्हों, घुटनों और टखनों को तेजी से फैलाएं, बारबेल को ऊपर की ओर ले जाएं।","जैसे ही बारबेल छाती के स्तर पर पहुंचे, इसे अपने शरीर के करीब रखते हुए अपनी बांह से ऊपर की ओर खींचें।","अपनी कोहनी को बारबेल के नीचे घुमाएं और अपनी कोहनी को लॉक करते हुए अपने हाथ को पूरी तरह ऊपर की ओर फैलाएं।","नियंत्रित तरीके से बारबेल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0068', 'Barbell One Leg Squat', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'barbell', 'strength', 'expert', '["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Lift one foot off the ground and extend it forward, keeping it parallel to the ground.","Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.","Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी पीठ के ऊपरी हिस्से पर एक बारबेल पकड़ें।","एक पैर को जमीन से ऊपर उठाएं और इसे जमीन के समानांतर रखते हुए आगे की ओर फैलाएं।","अपने खड़े पैर को मोड़ें और अपने शरीर को नीचे नीचे करें जैसे कि आप कुर्सी पर बैठे हों, अपनी छाती को ऊपर और अपनी पीठ को सीधा रखें।","जब तक आपकी जांघ जमीन के समानांतर न हो जाए, तब तक अपने आप को नीचे रखें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ी से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदलें और दोहराएं।"]', '["One_Leg_Barbell_Squat/0.jpg","One_Leg_Barbell_Squat/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0069', 'Barbell Overhead Squat', 'upper legs', 'quads', '["glutes","hamstrings","calves","core"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell with a wide grip, positioning it overhead with your arms fully extended.","Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और पंजों को थोड़ा बाहर की ओर करके खड़े हो जाएं।","बारबेल को चौड़ी पकड़ से पकड़ें, अपनी भुजाओं को पूरी तरह फैलाकर इसे सिर के ऊपर रखें।","अपने कोर को संलग्न करें और अपने शरीर को स्क्वाट स्थिति में नीचे लाएं, अपनी छाती को ऊपर रखें और घुटनों को अपने पैर की उंगलियों पर रखें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1411', 'Barbell Palms Down Wrist Curl Over A Bench', 'lower arms', 'forearms', '["biceps","brachialis"]', 'barbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down.","Hold a barbell with an overhand grip, hands shoulder-width apart.","Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary.","Pause for a moment at the bottom, then slowly raise the barbell back up by extending your wrists.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने अग्रभागों को अपनी जाँघों पर टिकाकर, हथेलियाँ नीचे की ओर रखते हुए एक बेंच पर बैठें।","हाथों को कंधे की चौड़ाई से अलग रखते हुए बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपनी कलाइयों को मोड़कर, अपने अग्रबाहुओं को स्थिर रखते हुए, बारबेल को ज़मीन की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे अपनी कलाइयों को फैलाकर बारबेल को वापस ऊपर उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1412', 'Barbell Palms Up Wrist Curl Over A Bench', 'lower arms', 'forearms', '["biceps","shoulders"]', 'barbell', 'strength', 'beginner', '["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को जमीन पर सपाट करके एक बेंच पर बैठें और हथेलियाँ ऊपर की ओर रखते हुए बारबेल को हाथ से पकड़ें।","अपनी बांहों को बेंच पर टिकाएं, जिससे आपकी कलाइयां किनारे से लटक जाएं।","अपने अग्रबाहुओं को स्थिर रखते हुए सांस छोड़ें और जहां तक ​​संभव हो अपनी कलाइयों को ऊपर की ओर मोड़ें।","थोड़ी देर के लिए सिकुड़ी हुई स्थिति में बने रहें, फिर सांस लें और धीरे-धीरे बारबेल को वापस शुरुआती स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg","Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-3017', 'Barbell Pendlay Row', 'back', 'upper back', '["biceps","forearms"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.","Bend forward at the hips, keeping your back straight and your chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","अपनी पीठ सीधी और छाती ऊपर रखते हुए कूल्हों के बल आगे की ओर झुकें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बारबेल को अपने ऊपरी पेट की ओर खींचें।","बारबेल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1751', 'Barbell Pin Presses', 'upper arms', 'triceps', '["shoulders"]', 'barbell', 'strength', NULL, '["Set up a barbell on a power rack at chest height.","Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart.","Grip the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest, with your arms fully extended.","Lower the barbell down towards your chest, keeping your elbows tucked in close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["छाती की ऊंचाई पर पावर रैक पर बारबेल स्थापित करें।","बारबेल की ओर मुंह करके खड़े हो जाएं और अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए खुद को इसके नीचे रखें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","बारबेल को रैक से उठाएं और अपनी बाहों को पूरी तरह फैलाकर सीधे अपनी छाती के ऊपर रखें।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए, बारबेल को अपनी छाती की ओर नीचे करें।","जब बारबेल आपकी छाती को छूए तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0070', 'Barbell Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', NULL, '["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी ऊपरी बांहों को पैड पर और अपनी छाती को सहारे पर टिकाकर एक उपदेशक बेंच पर बैठें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","अपनी ऊपरी बांहों को स्थिर रखते हुए सांस छोड़ें और बारबेल को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0071', 'Barbell Press Sit-Up', 'waist', 'abs', '["shoulders","chest"]', 'barbell', 'strength', NULL, '["Lie flat on your back on a mat with your knees bent and feet flat on the ground.","Hold the barbell with an overhand grip, resting it on your chest.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए एक चटाई पर अपनी पीठ के बल लेट जाएँ।","बारबेल को अपनी छाती पर टिकाकर, ऊपरी पकड़ से पकड़ें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0072', 'Barbell Prone Incline Curl', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting against it.","Hold a barbell with an underhand grip, shoulder-width apart.","Extend your arms fully, allowing the barbell to hang down towards the floor.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","अपनी छाती और पेट को बेंच पर टिकाकर चेहरे के बल लेट जाएँ।","बारबेल को कंधे की चौड़ाई की दूरी पर हाथ की पकड़ से पकड़ें।","अपनी बाहों को पूरी तरह फैलाएं, जिससे बारबेल नीचे फर्श की ओर लटक जाए।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","बारबेल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बारबेल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0073', 'Barbell Pullover', 'back', 'lats', '["chest","triceps"]', 'barbell', 'strength', NULL, '["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपने सिर को एक छोर पर और अपने पैरों को फर्श पर रखकर सीधे लेट जाएं।","कंधे की चौड़ाई की पकड़ के साथ बारबेल को पकड़ें और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएं।","अपनी भुजाओं को सीधा रखते हुए, बारबेल को अपने सिर के पीछे नियंत्रित तरीके से तब तक नीचे करें जब तक आपको अपनी जांघों में खिंचाव महसूस न हो।","एक पल के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0022', 'Barbell Pullover To Press', 'back', 'lats', '["triceps","chest","shoulders"]', 'barbell', 'strength', NULL, '["Lie flat on a bench with your head at one end and your feet on the ground.","Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.","Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपने सिर को एक छोर पर और अपने पैरों को ज़मीन पर रखकर सीधे लेट जाएँ।","बारबेल को उभरी हुई पकड़ से पकड़ें (हथेलियाँ आपसे दूर की ओर हों) और अपनी भुजाओं को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी भुजाओं को सीधा रखते हुए, बारबेल को अपने सिर के पीछे एक चाप जैसी गति में तब तक नीचे करें जब तक आपको अपनी जांघों में खिंचाव महसूस न हो जाए।","एक पल के लिए रुकें, फिर गति को उल्टा करें और बारबेल को वापस अपनी छाती के ऊपर प्रारंभिक स्थिति में दबाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0074', 'Barbell Rack Pull', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'barbell', 'strength', NULL, '["Set up a barbell on a rack at knee height.","Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.","Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top.","Lower the barbell back down to the starting position by bending at the hips and knees.","Repeat for the desired number of repetitions."]', '["घुटने की ऊंचाई पर एक रैक पर बारबेल स्थापित करें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर की ओर हों।","अपने आप को नीचे लाने के लिए कूल्हों और घुटनों पर झुकें और हाथों को कंधे की चौड़ाई से अलग रखते हुए बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपने कोर को संलग्न करें और अपने कूल्हों और घुटनों को फैलाकर, अपने कंधों को पीछे खींचकर और शीर्ष पर अपने ग्लूट्स को निचोड़कर बारबेल को ऊपर उठाएं।","कूल्हों और घुटनों पर झुकते हुए बारबेल को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0075', 'Barbell Rear Delt Raise', 'shoulders', 'delts', '["traps","rhomboids"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और हथेलियां नीचे की ओर रखते हुए बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी भुजाओं को सीधा रखते हुए बारबेल को बगल की ओर उठाएं, जब तक कि वे जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0076', 'Barbell Rear Delt Row', 'shoulders', 'delts', '["trapezius","rhomboids","biceps"]', 'barbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी पीठ सीधी और छाती ऊपर रखते हुए कूल्हों के बल आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बारबेल को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Barbell_Rear_Delt_Row/0.jpg","Barbell_Rear_Delt_Row/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0078', 'Barbell Rear Lunge', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'barbell', 'strength', NULL, '["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और एक बारबेल को अपनी पीठ के ऊपरी हिस्से पर टिकाकर खड़े होकर शुरुआत करें।","अपने दाहिने पैर से एक कदम पीछे ले जाएं, अपने पैर की गेंद पर उतरें।","अपने शरीर को नीचे करने के लिए दोनों घुटनों को मोड़ें जब तक कि आपकी बाईं जांघ जमीन के समानांतर न हो जाए।","प्रारंभिक स्थिति में लौटने के लिए अपनी बायीं एड़ी को धक्का दें।","दूसरे पैर से दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0077', 'Barbell Rear Lunge v. 2', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी पीठ के ऊपरी हिस्से पर एक बारबेल पकड़ें।","अपने दाहिने पैर से एक कदम पीछे ले जाएं, अपने पैर की गेंद पर उतरें।","अपने शरीर को नीचे करने के लिए दोनों घुटनों को मोड़ें जब तक कि आपकी बाईं जांघ जमीन के समानांतर न हो जाए।","प्रारंभिक स्थिति में लौटने के लिए अपनी बायीं एड़ी को धक्का दें।","दूसरे पैर से दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0079', 'Barbell Revers Wrist Curl v. 2', 'lower arms', 'forearms', '["biceps","brachialis"]', 'barbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and your knees bent.","Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को मोड़कर एक बेंच पर बैठें।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों और आपके हाथ कंधे की चौड़ाई से अलग हों।","अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ, जिससे आपकी कलाइयाँ किनारे से लटक जाएँ।","अपनी बांहों को स्थिर रखते हुए सांस छोड़ें और जहां तक ​​संभव हो अपनी कलाइयों को ऊपर की ओर मोड़ें।","थोड़ी देर के लिए सिकुड़ी हुई स्थिति में बने रहें, फिर सांस लें और धीरे-धीरे बारबेल को वापस शुरुआती स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2187', 'Barbell Reverse Close-Grip Bench Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'barbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a reverse grip, hands shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell down towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell is just above your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","हाथों को कंधे की चौड़ाई से अलग रखते हुए बारबेल को उल्टी पकड़ से पकड़ें।","बारबेल को रैक से उठाएं और अपनी बाहों को पूरी तरह फैलाकर सीधे अपनी छाती के ऊपर पकड़ें।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए बारबेल को धीरे-धीरे अपनी छाती की ओर नीचे लाएं।","जब बारबेल आपकी छाती के ठीक ऊपर हो तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0080', 'Barbell Reverse Curl', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', 'beginner', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखते हुए सीधे खड़े हो जाएं और हथेलियों को नीचे की ओर रखते हुए बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपनी ऊपरी भुजाओं को स्थिर रखें और अपने बाइसेप्स को सिकोड़ते हुए बारबेल को ऊपर की ओर मोड़ते हुए सांस छोड़ें।","बारबेल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बारबेल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","सांस लेते हुए धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में लाएं, अपनी ऊपरी भुजाओं को स्थिर रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Reverse_Barbell_Curl/0.jpg","Reverse_Barbell_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0118', 'Barbell Reverse Grip Bent Over Row', 'back', 'upper back', '["biceps","forearms"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों और हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","अपनी पीठ सीधी और छाती ऊपर रखते हुए कूल्हों के बल आगे की ओर झुकें, जब तक कि आपका धड़ लगभग फर्श के समानांतर न हो जाए।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बारबेल को अपनी निचली छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1256', 'Barbell Reverse Grip Decline Bench Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'barbell', 'strength', NULL, '["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को सुरक्षित रखते हुए और अपने सिर को अपने कूल्हों से नीचे करके एक डिक्लाइन बेंच पर लेटें।","बारबेल को कंधे की चौड़ाई से थोड़ा चौड़ा करके उल्टी पकड़ से पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को अंदर की ओर रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1257', 'Barbell Reverse Grip Incline Bench Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'barbell', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","अपने पैरों को ज़मीन पर सपाट करके बेंच पर लेट जाएँ।","बारबेल को उल्टी पकड़ से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","बारबेल को खोलें और अपनी कोहनियों को अंदर की ओर रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","जब बारबेल आपकी छाती को छूए तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1317', 'Barbell Reverse Grip Incline Bench Row', 'back', 'upper back', '["biceps","forearms"]', 'barbell', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Sit on the bench facing the backrest with your chest against it.","Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.","Keep your back straight and core engaged.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","बेंच पर बैकरेस्ट की ओर मुंह करके अपनी छाती को टिकाकर बैठें।","बारबेल को उल्टी पकड़ (हथेलियाँ नीचे की ओर) से पकड़ें और हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी पीठ सीधी और कोर व्यस्त रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बारबेल को अपने ऊपरी पेट की ओर खींचें।","गति के शीर्ष पर एक क्षण के लिए रुकें।","बारबेल को धीरे-धीरे प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1721', 'Barbell Reverse Grip Skullcrusher', 'upper arms', 'triceps', '["forearms"]', 'barbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart.","Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.","Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपने पैरों को ज़मीन पर सपाट करके और अपने सिर को बेंच के अंत में रखकर सीधे लेट जाएँ।","बारबेल को उल्टी पकड़ से पकड़ें, हथेलियाँ आपके चेहरे की ओर हों और आपके हाथ कंधे की चौड़ाई से अलग हों।","अपनी बाहों को अपनी छाती के ऊपर सीधा फैलाएं, अपनी कोहनियों को अंदर और अपनी कलाइयों को सीधा रखें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे बारबेल को अपने माथे की ओर नीचे लाएँ।","नीचे एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0081', 'Barbell Reverse Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', NULL, '["Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.","Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["एक उपदेशक बेंच पर अपनी छाती को पैड से सटाकर बैठें और आपकी भुजाएँ सीधी नीचे की ओर फैली हुई हों, एक बारबेल को ओवरहैंड पकड़ के साथ पकड़ें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए बारबेल को ऊपर की ओर मोड़ें।","बारबेल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बारबेल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे बारबेल को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0082', 'Barbell Reverse Wrist Curl', 'lower arms', 'forearms', '["biceps","brachialis"]', 'barbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the barbell towards your body.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और हथेलियाँ नीचे की ओर रखते हुए बारबेल को ज़ोर से पकड़ें।","अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ, जिससे आपकी कलाइयाँ किनारे से लटक जाएँ।","धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, बारबेल को अपने शरीर की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0084', 'Barbell Rollerout', 'waist', 'abs', '["lower back"]', 'barbell', 'strength', NULL, '["Kneel on the floor and hold a barbell with both hands, shoulder-width apart.","Roll the barbell forward, extending your arms and keeping your core engaged.","Continue rolling forward until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control.","Repeat for the desired number of repetitions."]', '["फर्श पर घुटने टेकें और दोनों हाथों से कंधे की चौड़ाई की दूरी पर बारबेल पकड़ें।","अपनी बाहों को फैलाते हुए और अपने कोर को व्यस्त रखते हुए, बारबेल को आगे की ओर घुमाएँ।","जब तक आपका शरीर पूरी तरह से विस्तारित न हो जाए और आपकी भुजाएं ऊपर न आ जाएं, तब तक आगे की ओर लुढ़कना जारी रखें।","एक पल के लिए रुकें, फिर नियंत्रण बनाए रखते हुए धीरे-धीरे बारबेल को अपने घुटनों की ओर वापस घुमाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0083', 'Barbell Rollerout From Bench', 'waist', 'abs', '["shoulders","triceps"]', 'barbell', 'strength', NULL, '["Start by kneeling on the floor with a barbell placed on a bench in front of you.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you.","Continue rolling the barbell forward until your body is fully extended and your arms are overhead.","Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position.","Repeat for the desired number of repetitions."]', '["अपने सामने एक बेंच पर बारबेल रखकर फर्श पर घुटने टेककर शुरुआत करें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","अपने कोर को व्यस्त रखते हुए और अपनी पीठ को सीधा रखते हुए, अपनी बाहों को अपने सामने फैलाते हुए धीरे-धीरे बारबेल को आगे की ओर घुमाएँ।","जब तक आपका शरीर पूरी तरह से विस्तारित न हो जाए और आपकी भुजाएं ऊपर न आ जाएं, तब तक बारबेल को आगे की ओर घुमाते रहें।","पूरी तरह से विस्तारित स्थिति में एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को अपने शरीर की ओर घुमाएं, प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0085', 'Barbell Romanian Deadlift', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and your toes pointing forward.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend at the hips, keeping your back straight and your knees slightly bent.","Lower the barbell towards the ground, keeping it close to your body.","Feel the stretch in your hamstrings as you lower the barbell.","Once you feel a stretch in your hamstrings, push your hips forward and stand up straight.","Squeeze your glutes at the top of the movement.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके पैर की उंगलियां आगे की ओर हों।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी पीठ को सीधा रखते हुए और अपने घुटनों को थोड़ा मोड़ते हुए, कूल्हों पर झुकें।","बारबेल को अपने शरीर के करीब रखते हुए जमीन की ओर नीचे करें।","जैसे ही आप बारबेल को नीचे करते हैं, अपनी हैमस्ट्रिंग में खिंचाव महसूस करें।","एक बार जब आप अपनी हैमस्ट्रिंग में खिंचाव महसूस करें, तो अपने कूल्हों को आगे की ओर धकेलें और सीधे खड़े हो जाएं।","आंदोलन के शीर्ष पर अपने ग्लूट्स को निचोड़ें।","बारबेल को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0086', 'Barbell Seated Behind Head Military Press', 'shoulders', 'delts', '["triceps","upper back"]', 'barbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it down to shoulder level, behind your head.","Press the barbell upward until your arms are fully extended.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","बारबेल को रैक से उठाएं और इसे अपने सिर के पीछे, कंधे के स्तर तक नीचे लाएं।","बारबेल को तब तक ऊपर की ओर दबाएँ जब तक आपकी भुजाएँ पूरी तरह विस्तारित न हो जाएँ।","बारबेल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0087', 'Barbell Seated Bradford Rocky Press', 'shoulders', 'delts', '["triceps","upper back"]', 'barbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.","Press the barbell overhead, fully extending your arms.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","बारबेल को कंधे की ऊंचाई तक उठाएं, अपनी कोहनियों को थोड़ा मोड़कर आगे की ओर रखें।","अपनी बाहों को पूरी तरह फैलाकर बारबेल को ऊपर की ओर दबाएं।","बारबेल को वापस कंधे की ऊंचाई तक कम करें और वांछित संख्या में दोहराव के लिए दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0088', 'Barbell Seated Calf Raise', 'lower legs', 'calves', '["hamstrings","quadriceps"]', 'barbell', 'strength', 'beginner', '["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Place the balls of your feet on a raised platform, such as a block or step.","Position the barbell across your thighs and hold it securely with your hands.","Keeping your back straight and your core engaged, lift your heels off the ground by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फर्श पर सपाट करके और एक बारबेल को अपनी जांघों पर टिकाकर एक बेंच पर बैठें।","अपने पैरों की उंगलियों को किसी ऊंचे मंच पर रखें, जैसे ब्लॉक या सीढ़ी।","बारबेल को अपनी जांघों पर रखें और इसे अपने हाथों से सुरक्षित रूप से पकड़ें।","अपनी पीठ सीधी और अपने कोर को व्यस्त रखते हुए, अपनी एड़ियों को फैलाकर अपनी एड़ियों को जमीन से ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Barbell_Seated_Calf_Raise/0.jpg","Barbell_Seated_Calf_Raise/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1371', 'Barbell Seated Calf Raise', 'lower legs', 'calves', '["hamstrings"]', 'barbell', 'strength', 'beginner', '["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Place the balls of your feet on a raised platform, such as a block or step.","Lower your heels as far as possible, feeling a stretch in your calves.","Raise your heels as high as possible, contracting your calves.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फर्श पर सपाट करके और एक बारबेल को अपनी जांघों पर टिकाकर एक बेंच पर बैठें।","अपने पैरों की उंगलियों को किसी ऊंचे मंच पर रखें, जैसे ब्लॉक या सीढ़ी।","जहां तक ​​संभव हो अपनी एड़ियों को नीचे करें, अपनी पिंडलियों में खिंचाव महसूस करें।","अपनी पिंडलियों को सिकोड़ते हुए अपनी एड़ियों को जितना संभव हो उतना ऊपर उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Barbell_Seated_Calf_Raise/0.jpg","Barbell_Seated_Calf_Raise/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1718', 'Barbell Seated Close Grip Behind Neck Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'barbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with a close grip behind your neck, palms facing forward.","Keep your elbows close to your head and slowly lower the barbell towards the back of your head.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","बारबेल को अपनी गर्दन के पीछे कसकर पकड़ें, हथेलियाँ आगे की ओर हों।","अपनी कोहनियों को अपने सिर के पास रखें और बारबेल को धीरे-धीरे अपने सिर के पीछे की ओर नीचे करें।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0089', 'Barbell Seated Close-Grip Concentration Curl', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', 'intermediate', '["Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.","Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फर्श पर सपाट करके एक बेंच पर बैठें और हाथों को कंधे की चौड़ाई से अलग रखते हुए बारबेल को हाथ से पकड़ें।","अपनी ऊपरी भुजाओं को अपने घुटनों के ठीक ऊपर, अपनी भीतरी जाँघों पर टिकाएँ, और बारबेल को अपने सामने नीचे लटकने दें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए बारबेल को अपने कंधों की ओर मोड़ें।","थोड़ी देर के लिए सिकुड़ी हुई स्थिति में बने रहें, फिर सांस लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Seated_Close-Grip_Concentration_Barbell_Curl/0.jpg","Seated_Close-Grip_Concentration_Barbell_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0090', 'Barbell Seated Good Morning', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'barbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.","Keep your back straight and your chest up.","Slowly hinge forward at the hips, lowering your torso towards the ground.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और एक बारबेल आपकी पीठ के ऊपरी हिस्से पर टिका हुआ हो।","अपनी पीठ सीधी और छाती ऊपर रखें।","अपने धड़ को जमीन की ओर नीचे करते हुए धीरे-धीरे कूल्हों पर आगे की ओर झुकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0091', 'Barbell Seated Overhead Press', 'shoulders', 'delts', '["triceps","upper back"]', 'barbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.","Press the barbell overhead by extending your arms fully.","Pause for a moment at the top, then slowly lower the barbell back to shoulder level.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","बारबेल को रैक से उठाएं और कंधे के स्तर पर लाएं, अपनी कोहनियां मुड़ी हुई और हथेलियां आगे की ओर रहें।","अपनी बाहों को पूरी तरह फैलाकर बारबेल को ऊपर की ओर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस कंधे के स्तर तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-0092', 'Barbell Seated Overhead Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'barbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead.","Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.","Pause for a moment, then extend your arms to raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","बारबेल को ऊपरी पकड़ से पकड़ें, हाथों को कंधे की चौड़ाई से अलग रखें और इसे ऊपर उठाएं।","अपनी कोहनियों को मोड़कर बारबेल को अपने सिर के पीछे नीचे करें, अपनी ऊपरी भुजाओं को अपने सिर के पास रखें।","एक पल के लिए रुकें, फिर बारबेल को शुरुआती स्थिति में वापस उठाने के लिए अपनी बाहों को फैलाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0094', 'Barbell Seated Twist', 'waist', 'abs', '["obliques","lower back"]', 'barbell', 'strength', 'beginner', '["Sit on a flat bench with your feet flat on the ground and your knees bent.","Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent.","Engage your core and slowly twist your torso to one side, keeping your back straight.","Pause for a moment at the end of the twist, then slowly rotate back to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को मोड़कर एक सपाट बेंच पर बैठें।","अपनी कोहनियों को थोड़ा मुड़ा हुआ रखते हुए, अपनी छाती के सामने दोनों हाथों से बारबेल को पकड़ें।","अपने कोर को संलग्न करें और अपनी पीठ को सीधा रखते हुए धीरे-धीरे अपने धड़ को एक तरफ मोड़ें।","मोड़ के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में वापस आएँ।","दूसरी तरफ मोड़ को दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', '["Seated_Barbell_Twist/0.jpg","Seated_Barbell_Twist/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0095', 'Barbell Shrug', 'back', 'traps', '["shoulders"]', 'barbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip.","Keep your arms straight and your back straight throughout the exercise.","Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top.","Hold for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपने सामने एक बारबेल को ज़ोर से पकड़ें।","पूरे अभ्यास के दौरान अपनी भुजाएँ सीधी और अपनी पीठ सीधी रखें।","अपने कंधों को अपने कानों की ओर जितना संभव हो उतना ऊपर उठाएं, अपने जालों को शीर्ष पर निचोड़ें।","एक पल के लिए रुकें, फिर धीरे-धीरे अपने कंधों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Barbell_Shrug/0.jpg","Barbell_Shrug/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0096', 'Barbell Side Bent v. 2', 'waist', 'abs', '["obliques","lower back"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.","Keep your back straight and core engaged throughout the exercise.","Slowly bend your torso to the right side, lowering the barbell towards your right knee.","Pause for a moment, then return to the starting position.","Repeat the movement on the left side.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों से बारबेल पकड़ें, हथेलियां नीचे की ओर हों।","पूरे अभ्यास के दौरान अपनी पीठ सीधी रखें और मुख्य भाग को व्यस्त रखें।","धीरे-धीरे अपने धड़ को दाहिनी ओर झुकाएं, बारबेल को अपने दाहिने घुटने की ओर नीचे करें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौट आएं।","बायीं ओर भी यही क्रिया दोहरायें।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0098', 'Barbell Side Split Squat', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'barbell', 'strength', 'beginner', '["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold a barbell across your upper back, resting it on your traps.","Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.","As you lower, push your knees out to the sides and keep your weight on your heels.","Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अधिक चौड़ा करके खड़े रहें, पैर की उंगलियां थोड़ी बाहर की ओर हों।","अपनी ऊपरी पीठ पर एक बारबेल पकड़ें, इसे अपने जाल पर टिकाएं।","अपने कोर को संलग्न करें और घुटनों और कूल्हों पर झुकते हुए अपने शरीर को स्क्वाट स्थिति में नीचे लाते समय अपनी छाती को ऊपर रखें।","जैसे ही आप नीचे आते हैं, अपने घुटनों को बगल की ओर धकेलें और अपना वजन अपनी एड़ियों पर रखें।","जब तक आपकी जांघें जमीन के समानांतर न हो जाएं, तब तक नीचे झुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Barbell_Side_Split_Squat/0.jpg","Barbell_Side_Split_Squat/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0097', 'Barbell Side Split Squat v. 2', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'barbell', 'strength', NULL, '["Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards.","Hold a barbell across your upper back, resting it on your shoulders.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight.","Push through your right heel to return to the starting position.","Repeat on the other side, stepping out with your left foot.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अधिक चौड़ा करके खड़े रहें, पैर की उंगलियां थोड़ी बाहर की ओर हों।","अपनी ऊपरी पीठ पर एक बारबेल पकड़ें, इसे अपने कंधों पर टिकाएं।","अपने दाहिने पैर को बगल में रखते हुए एक बड़ा कदम उठाएं, अपने बाएं पैर को सीधा रखें।","अपने दाहिने घुटने को मोड़ें और अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ, अपनी छाती को ऊपर और अपनी पीठ को सीधा रखें।","प्रारंभिक स्थिति में लौटने के लिए अपनी दाहिनी एड़ी को धक्का दें।","अपने बाएं पैर से बाहर निकलते हुए दूसरी तरफ भी दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1756', 'Barbell Single Leg Deadlift', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'barbell', 'strength', NULL, '["Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.","Shift your weight onto your left foot and lift your right foot slightly off the ground.","Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.","Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कूल्हे-चौड़ाई से अलग करके खड़े हो जाएं, एक बारबेल को अपनी जांघों के सामने एक ओवरहैंड पकड़ के साथ पकड़ें।","अपना वजन अपने बाएं पैर पर डालें और अपने दाहिने पैर को जमीन से थोड़ा ऊपर उठाएं।","कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी रखें और संतुलन के लिए अपना दाहिना पैर अपने पीछे फैलाएँ।","बारबेल को अपने शरीर के पास रखते हुए और अपने बाएँ पैर को थोड़ा मोड़कर ज़मीन की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपने धड़ को शुरुआती स्थिति में वापस उठाने के लिए अपने ग्लूट्स और हैमस्ट्रिंग को शामिल करें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0099', 'Barbell Single Leg Split Squat', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a large step forward with one leg, keeping your torso upright.","Lower your body by bending your front knee and hip, while keeping your back leg straight.","Continue lowering until your front thigh is parallel to the ground.","Pause for a moment, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपनी पीठ के ऊपरी हिस्से पर एक बारबेल पकड़ें।","अपने धड़ को सीधा रखते हुए एक पैर से एक बड़ा कदम आगे बढ़ाएं।","अपने पिछले पैर को सीधा रखते हुए, अपने सामने के घुटने और कूल्हे को मोड़कर अपने शरीर को नीचे लाएँ।","जब तक आपकी अगली जांघ ज़मीन के समानांतर न हो जाए, तब तक नीचे करना जारी रखें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी सामने की एड़ी से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2799', 'Barbell Sitted Alternate Leg Raise', 'waist', 'abs', '["hip flexors"]', 'barbell', 'strength', NULL, '["Sit on a bench with your back straight and hold a barbell across your thighs.","Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.","Lower the raised leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]', '["अपनी पीठ सीधी करके एक बेंच पर बैठें और अपनी जांघों पर एक बारबेल पकड़ें।","अपने पैरों को सीधा रखते हुए एक पैर को जितना हो सके ऊपर उठाएं और दूसरे पैर को जमीन पर रखें।","उठे हुए पैर को वापस नीचे लाएँ और दूसरे पैर से दोहराएँ।","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-2800', 'Barbell Sitted Alternate Leg Raise (Female)', 'waist', 'abs', '["hip flexors","quadriceps"]', 'barbell', 'strength', NULL, '["Sit on a bench with your back straight and hold a barbell across your thighs.","Place your hands on the sides of the bench for support.","Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.","Lower the leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]', '["अपनी पीठ सीधी करके एक बेंच पर बैठें और अपनी जांघों पर एक बारबेल पकड़ें।","समर्थन के लिए अपने हाथों को बेंच के किनारों पर रखें।","अपने पैरों को सीधा रखते हुए, एक पैर को जमीन के समानांतर रखते हुए जितना संभव हो उतना ऊपर उठाएं।","पैर को वापस नीचे लाएँ और दूसरे पैर से दोहराएँ।","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0100', 'Barbell Skier', 'shoulders', 'delts', '["triceps","core"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.","As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी जांघों के सामने एक बारबेल को ज़ोर से पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी और छाती ऊपर रखें।","इसके साथ ही जमीन से थोड़ा ऊपर उछलते हुए बारबेल को अपने कंधों की ओर ऊपर उठाएं।","जैसे ही आप गति के शीर्ष पर पहुँचते हैं, गति को तुरंत उलट दें और बारबेल को वापस प्रारंभिक स्थिति में ले आएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0101', 'Barbell Speed Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","बारबेल को अपनी ऊपरी पीठ पर पकड़ें, इसे अपने जाल या पीछे के डेल्टा पर टिकाएं।","अपने कोर को संलग्न करें और अपने कूल्हों को पीछे और नीचे करते समय अपनी छाती को ऊपर रखें, जैसे कि एक कुर्सी पर बैठे हों।","तब तक नीचे जाएँ जब तक आपकी जाँघें ज़मीन के समानांतर न हो जाएँ, या जितना नीचे आप आराम से जा सकें।","वापस खड़े होने के लिए अपनी एड़ियों के माध्यम से ड्राइव करें, शीर्ष पर अपने ग्लूट्स को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2810', 'Barbell Split Squat v. 2', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'barbell', 'strength', NULL, '["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Take a large step forward with your right foot, keeping your torso upright.","Lower your body by bending your knees and hips until your right thigh is parallel to the ground.","Pause for a moment, then push through your right heel to return to the starting position.","Repeat with your left leg forward for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर, अपनी पीठ के ऊपरी हिस्से पर एक बारबेल पकड़कर खड़े होकर शुरुआत करें।","अपने धड़ को सीधा रखते हुए अपने दाहिने पैर से एक बड़ा कदम आगे बढ़ाएं।","अपने घुटनों और कूल्हों को मोड़कर अपने शरीर को नीचे करें जब तक कि आपकी दाहिनी जांघ जमीन के समानांतर न हो जाए।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी दाहिनी एड़ी से धक्का दें।","दोहराव की वांछित संख्या के लिए अपने बाएं पैर को आगे की ओर करके दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0102', 'Barbell Squat (On Knees)', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'barbell', 'strength', NULL, '["Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.","Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.","Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को कूल्हे की चौड़ाई से अलग रखते हुए और अपने पैर की उंगलियों को आगे की ओर रखते हुए जमीन पर घुटने टेककर शुरुआत करें।","अपने कंधों पर एक बारबेल रखें, इसे ओवरहैंड ग्रिप से पकड़ें और अपने हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपने कोर को संलग्न करें और अपनी छाती को ऊपर उठाकर रखें और धीरे-धीरे अपने घुटनों को मोड़कर, अपनी पीठ को सीधा रखते हुए अपने शरीर को नीचे लाएँ।","तब तक नीचे उतरना जारी रखें जब तक कि आपकी जांघें ज़मीन के समानांतर न हो जाएं, या उतना नीचे न आ जाएं जितना आप आराम से जा सकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2798', 'Barbell Squat Jump Step Rear Lunge', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'barbell', 'strength', NULL, '["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Lower your body into a squat position by bending your knees and pushing your hips back.","Explode upwards, jumping off the ground as high as you can.","Land softly on your feet and immediately step back with one leg into a reverse lunge.","Lower your body down until your front thigh is parallel to the ground, keeping your back straight.","Push through your front heel to return to the starting position.","Repeat the jump and lunge sequence on the other leg.","Continue alternating legs for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर, अपनी पीठ के ऊपरी हिस्से पर एक बारबेल पकड़कर खड़े होकर शुरुआत करें।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को स्क्वाट स्थिति में लाएँ।","ऊपर की ओर विस्फोट करें, जितना हो सके ज़मीन से ऊपर उछलें।","अपने पैरों पर धीरे से बैठें और तुरंत एक पैर को उल्टा करके पीछे हटें।","अपने शरीर को तब तक नीचे झुकाएँ जब तक कि आपकी अगली जांघ ज़मीन के समानांतर न हो जाए, अपनी पीठ सीधी रखें।","प्रारंभिक स्थिति में लौटने के लिए अपनी सामने की एड़ी को धक्का दें।","दूसरे पैर पर कूदने और झपटने का क्रम दोहराएं।","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0103', 'Barbell Standing Ab Rollerout', 'waist', 'abs', '["shoulders","lower back"]', 'barbell', 'strength', NULL, '["Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.","Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended.","Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head.","Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं और दोनों हाथों से बारबेल को अपनी जांघों के सामने पकड़ लें।","अपने कोर को संलग्न करें और धीरे-धीरे बारबेल को जमीन की ओर घुमाएं, अपनी पीठ को सीधा रखें और अपनी बाहों को फैलाएं।","जब तक आपका शरीर पूरी तरह से विस्तारित न हो जाए और आपके हाथ सीधे आपके सिर के ऊपर न आ जाएं, तब तक बारबेल को आगे की ओर घुमाते रहें।","एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस अपनी जांघों की ओर घुमाएं, नियंत्रण बनाए रखें और अपने कोर को व्यस्त रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0104', 'Barbell Standing Back Wrist Curl', 'lower arms', 'forearms', '["biceps","shoulders"]', 'barbell', 'strength', NULL, '["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip.","Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body.","Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं और बारबेल को ओवरहैंड ग्रिप से पकड़ लें।","अपनी हथेलियों को नीचे की ओर रखते हुए और अपनी उंगलियों को अपने शरीर की ओर रखते हुए बारबेल को अपने हाथों के पीछे रखें।","अपनी ऊपरी बांहों को स्थिर रखते हुए सांस छोड़ें और जहां तक ​​संभव हो अपनी कलाइयों को ऊपर की ओर मोड़ें।","थोड़ी देर के लिए सिकुड़ी हुई स्थिति में बने रहें, फिर सांस लें और धीरे-धीरे बारबेल को वापस शुरुआती स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0105', 'Barbell Standing Bradford Press', 'shoulders', 'delts', '["triceps","upper back"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip.","Press the barbell overhead, fully extending your arms.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बारबेल को अपने कंधों के सामने एक ऊपरी पकड़ के साथ पकड़ें।","अपनी बाहों को पूरी तरह फैलाकर बारबेल को ऊपर की ओर दबाएं।","बारबेल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1372', 'Barbell Standing Calf Raise', 'lower legs', 'calves', '["hamstrings","glutes"]', 'barbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and place a barbell across your upper back.","Raise your heels off the ground as high as possible, using only your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी पीठ के ऊपरी हिस्से पर एक बारबेल रखें।","केवल अपने पैर की उंगलियों का उपयोग करते हुए, अपनी एड़ियों को जमीन से जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Standing_Barbell_Calf_Raise/0.jpg","Standing_Barbell_Calf_Raise/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0106', 'Barbell Standing Close Grip Curl', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', 'beginner', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to bring the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं और हाथों को एक-दूसरे से सटाकर बारबेल को हाथ से पकड़ लें।","पूरे आंदोलन के दौरान अपनी कोहनियों को अपने धड़ के पास और अपनी ऊपरी भुजाओं को स्थिर रखें।","अपने बाइसेप्स को सिकोड़ते हुए वजन मोड़ते समय सांस छोड़ें। जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बार कंधे के स्तर पर न आ जाए, तब तक बार को ऊपर उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","जब आप धीरे-धीरे बारबेल को प्रारंभिक स्थिति में वापस लाना शुरू करें तो श्वास लें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Close-Grip_Standing_Barbell_Curl/0.jpg","Close-Grip_Standing_Barbell_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1456', 'Barbell Standing Close Grip Military Press', 'shoulders', 'delts', '["triceps","upper back"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart.","Lift the barbell to shoulder height, keeping your elbows close to your body.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं और बारबेल को हाथ से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े करीब हों।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए बारबेल को कंधे की ऊंचाई तक उठाएं।","अपनी बाहों को पूरी तरह फैलाते हुए बारबेल को ऊपर की ओर दबाएं।","बारबेल को वापस कंधे की ऊंचाई तक नीचे लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2414', 'Barbell Standing Concentration Curl', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up.","Rest your opposite hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the weight back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में बारबेल पकड़ लें, हथेली ऊपर की ओर हो।","समर्थन के लिए अपने उल्टे हाथ को अपनी जांघ पर रखें।","अपनी ऊपरी बांह को स्थिर रखते हुए सांस छोड़ें और वजन को अपने कंधे की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे वजन वापस प्रारंभिक स्थिति में लाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0107', 'Barbell Standing Front Raise Over Head', 'shoulders', 'delts', '["triceps","upper back"]', 'barbell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip.","Keep your back straight and engage your core.","Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.","Continue lifting until the barbell is slightly above shoulder level.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक बारबेल को अपनी जांघों के सामने एक ऊपरी पकड़ के साथ पकड़ें।","अपनी पीठ सीधी रखें और अपने कोर को संलग्न रखें।","धीरे-धीरे बारबेल को अपने सामने उठाएं, अपनी बाहों को सीधा रखें और अपनी हथेलियों को नीचे की ओर रखें।","तब तक उठाना जारी रखें जब तक बारबेल कंधे के स्तर से थोड़ा ऊपर न हो जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Standing_Front_Barbell_Raise_Over_Head/0.jpg","Standing_Front_Barbell_Raise_Over_Head/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0108', 'Barbell Standing Leg Calf Raise', 'lower legs', 'calves', '["hamstrings","glutes"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and place a barbell across your upper back.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी पीठ के ऊपरी हिस्से पर एक बारबेल रखें।","अपनी पिंडलियों का उपयोग करते हुए अपनी एड़ियों को जमीन से जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0109', 'Barbell Standing Overhead Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'barbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.","Raise the barbell overhead, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बारबेल को ओवरहैंड ग्रिप से पकड़ लें।","अपनी बाहों को पूरी तरह फैलाते हुए बारबेल को ऊपर उठाएं।","अपनी ऊपरी भुजाओं को अपने सिर के पास रखते हुए, अपनी कोहनियों को मोड़कर बारबेल को धीरे-धीरे अपने सिर के पीछे नीचे करें।","एक पल के लिए रुकें, फिर अपनी बाहों को फैलाकर बारबेल को शुरुआती स्थिति में वापस उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Standing_Overhead_Barbell_Triceps_Extension/0.jpg","Standing_Overhead_Barbell_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0110', 'Barbell Standing Reverse Grip Curl', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', NULL, '["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं और हथेलियां ऊपर की ओर रखते हुए बारबेल को हाथ से पकड़ें।","अपनी कोहनियों को अपने धड़ के पास रखें और अपनी ऊपरी भुजाओं को स्थिर रखें।","सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें, बारबेल को जितना संभव हो सके अपने कंधों के करीब लाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे बारबेल को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0111', 'Barbell Standing Rocking Leg Calf Raise', 'lower legs', 'calves', '["hamstrings","quadriceps"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Raise your heels off the ground as high as possible, balancing on the balls of your feet.","Slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी पीठ के ऊपरी हिस्से पर एक बारबेल पकड़ें।","अपने पैरों की उंगलियों पर संतुलन बनाते हुए अपनी एड़ियों को जमीन से जितना संभव हो उतना ऊपर उठाएं।","धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0112', 'Barbell Standing Twist', 'waist', 'abs', '["obliques","lower back"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down.","Engage your core and keep your back straight throughout the exercise.","Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the left side.","Continue alternating twists for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर फैलाकर खड़े हो जाएं और दोनों हाथों से अपनी छाती के सामने एक बारबेल पकड़ें, हथेलियाँ नीचे की ओर हों।","पूरे अभ्यास के दौरान अपने कोर को व्यस्त रखें और अपनी पीठ सीधी रखें।","धीरे-धीरे अपने धड़ को दाहिनी ओर मोड़ें, अपने पैरों और कूल्हों पर घुमाएँ, जबकि अपने निचले शरीर को स्थिर रखें।","मोड़ के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","बाईं ओर मोड़ को दोहराएं।","पुनरावृत्ति की वांछित संख्या के लिए बारी-बारी से मोड़ जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1629', 'Barbell Standing Wide Grip Biceps Curl', 'upper arms', 'biceps', '["forearms"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart.","Keep your back straight and your elbows close to your torso.","Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े हो जाएं और बारबेल को हाथ से पकड़ें, हाथ कंधे की चौड़ाई से अधिक चौड़े हों।","अपनी पीठ सीधी रखें और अपनी कोहनियाँ अपने धड़ के पास रखें।","साँस छोड़ें और बारबेल को अपने कंधों की ओर मोड़ें, अपनी ऊपरी भुजाओं को स्थिर रखें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपनी बाहों को पूरी तरह फैलाते हुए बारबेल को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1457', 'Barbell Standing Wide Military Press', 'shoulders', 'delts', '["triceps","upper back"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width.","Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े हो जाएं और बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़ी पकड़ के साथ पकड़ें।","अपनी कोहनियों को बार के थोड़ा सामने रखते हुए बारबेल को कंधे की ऊंचाई तक उठाएं।","अपनी बाहों को पूरी तरह फैलाते हुए बारबेल को ऊपर की ओर दबाएं।","बारबेल को वापस कंधे की ऊंचाई तक कम करें और वांछित संख्या में दोहराव के लिए दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0113', 'Barbell Standing Wide-Grip Curl', 'upper arms', 'biceps', '["forearms","shoulders"]', 'barbell', 'strength', 'beginner', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Let the barbell hang at arm''s length in front of your thighs, with your palms facing away from your body.","Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए सीधे खड़े हो जाएं और हाथों को कंधे की चौड़ाई से ज्यादा चौड़ा रखते हुए बारबेल को ओवरहैंड ग्रिप से पकड़ें।","बारबेल को अपनी जाँघों के सामने एक हाथ की दूरी पर लटका दें, आपकी हथेलियाँ आपके शरीर से दूर की ओर हों।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़कर बारबेल को ऊपर की ओर मोड़ें।","बारबेल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बारबेल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Wide-Grip_Standing_Barbell_Curl/0.jpg","Wide-Grip_Standing_Barbell_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0114', 'Barbell Step-Up', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'barbell', 'strength', 'intermediate', '["Stand in front of a bench or step with a barbell resting on your upper back.","Place one foot on the bench or step, ensuring your entire foot is in contact with the surface.","Push through your heel and step up onto the bench or step, fully extending your hip and knee.","Pause briefly at the top, then lower yourself back down to the starting position.","Repeat with the opposite leg.","Continue alternating legs for the desired number of repetitions."]', '["अपनी पीठ के ऊपरी हिस्से पर बारबेल को टिकाकर किसी बेंच या स्टेप के सामने खड़े हो जाएं।","एक पैर को बेंच या सीढ़ी पर रखें, यह सुनिश्चित करते हुए कि आपका पूरा पैर सतह के संपर्क में है।","अपनी एड़ी के माध्यम से धक्का दें और अपने कूल्हे और घुटने को पूरी तरह से फैलाते हुए बेंच या सीढ़ी पर चढ़ें।","शीर्ष पर कुछ देर रुकें, फिर अपने आप को वापस प्रारंभिक स्थिति में ले आएं।","विपरीत पैर से दोहराएँ.","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"]', '["Barbell_Step_Ups/0.jpg","Barbell_Step_Ups/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0115', 'Barbell Stiff Leg Good Morning', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'barbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the barbell across your upper back, resting it on your traps.","Keeping your back straight, hinge forward at the hips, pushing your glutes back.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Engage your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","बारबेल को अपनी ऊपरी पीठ पर पकड़ें, इसे अपने जाल पर टिकाएं।","अपनी पीठ को सीधा रखते हुए, कूल्हों पर आगे की ओर झुकें, अपने ग्लूट्स को पीछे धकेलें।","अपने धड़ को तब तक नीचे करें जब तक वह ज़मीन के समानांतर न हो जाए, अपनी हैमस्ट्रिंग में खिंचाव महसूस करें।","प्रारंभिक स्थिति में लौटने के लिए अपने ग्लूट्स और हैमस्ट्रिंग को संलग्न करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Stiff_Leg_Barbell_Good_Morning/0.jpg","Stiff_Leg_Barbell_Good_Morning/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0116', 'Barbell Straight Leg Deadlift', 'upper legs', 'hamstrings', '["glutes","lower back"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and your toes pointing forward.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.","Lower the barbell until you feel a stretch in your hamstrings.","Engage your hamstrings and glutes to lift the barbell back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके पैर की उंगलियां आगे की ओर हों।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपने कूल्हों पर झुकें और बारबेल को ज़मीन की ओर नीचे करें, अपनी पीठ सीधी रखें और अपने घुटने थोड़े मुड़े हुए रखें।","जब तक आप अपनी हैमस्ट्रिंग में खिंचाव महसूस न करें तब तक बारबेल को नीचे रखें।","बारबेल को शुरुआती स्थिति में वापस उठाने के लिए अपनी हैमस्ट्रिंग और ग्लूट्स को शामिल करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0117', 'Barbell Sumo Deadlift', 'upper legs', 'glutes', '["hamstrings","quadriceps","lower back"]', 'barbell', 'strength', NULL, '["Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Place a barbell on the ground in front of you, centered between your feet.","Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.","Engage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously.","As you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अधिक चौड़ा करके खड़े रहें, पैर की उंगलियां बाहर की ओर हों।","अपने सामने ज़मीन पर एक बारबेल को अपने पैरों के बीच में रखें।","बारबेल को ओवरहैंड ग्रिप से पकड़ने के लिए अपने घुटनों को मोड़ें और अपने कूल्हों को नीचे करें, अपनी पीठ सीधी और छाती ऊपर रखें।","अपने कोर को संलग्न करें और अपने कूल्हों और घुटनों को एक साथ फैलाते हुए, बारबेल को जमीन से ऊपर उठाने के लिए अपनी एड़ी के माध्यम से ड्राइव करें।","जैसे ही आप उठाते हैं, अपनी छाती को ऊपर और पीठ को सीधा रखें, और अपने ग्लूट्स को पूरी तरह से संलग्न करने के लिए अपने कूल्हों को आगे की ओर धकेलें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को शुरुआती स्थिति में वापस लाएं, जिससे पूरे आंदोलन पर नियंत्रण बना रहे।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3305', 'Barbell Thruster', 'shoulders', 'delts', '["quadriceps","glutes","hamstrings","core"]', 'barbell', 'strength', NULL, '["Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip.","Lower into a squat position by bending your knees and pushing your hips back.","As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.","Lower the barbell back to shoulder height as you lower back into the squat position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े होकर शुरुआत करें, बारबेल को कंधे की ऊंचाई पर ओवरहैंड ग्रिप से पकड़ें।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए स्क्वाट स्थिति में आ जाएँ।","जैसे ही आप स्क्वाट के निचले भाग तक पहुँचते हैं, खड़े होने के लिए अपनी एड़ी के माध्यम से विस्फोटक रूप से ड्राइव करें, साथ ही बारबेल को ऊपर की ओर दबाएँ।","जैसे ही आप स्क्वाट स्थिति में वापस आते हैं, बारबेल को कंधे की ऊंचाई तक कम करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0120', 'Barbell Upright Row', 'shoulders', 'delts', '["traps","biceps"]', 'barbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े हो जाएं और बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","बारबेल को अपनी जाँघों के सामने लटका दें, बाहें पूरी तरह फैली हुई हों।","अपनी पीठ को सीधा और कोर को व्यस्त रखते हुए, सांस छोड़ें और बारबेल को अपनी कोहनियों की मदद से सीधे अपनी ठुड्डी की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Upright_Barbell_Row/0.jpg","Upright_Barbell_Row/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0119', 'Barbell Upright Row v. 2', 'shoulders', 'delts', '["traps","biceps"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े हो जाएं और बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","बारबेल को अपनी जाँघों के सामने लटका दें, बाहें पूरी तरह फैली हुई हों।","अपनी पीठ को सीधा रखते हुए, सांस छोड़ें और बारबेल को अपनी कोहनियों की मदद से सीधे अपनी ठुड्डी की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0121', 'Barbell Upright Row v. 3', 'shoulders', 'delts', '["traps","biceps"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े हो जाएं और बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","बारबेल को अपनी जाँघों के सामने लटका दें, बाहें पूरी तरह फैली हुई हों।","अपने कोर को व्यस्त रखते हुए और पीठ को सीधा रखते हुए, सांस छोड़ें और बारबेल को अपनी कोहनियों की ओर ले जाते हुए सीधे अपनी ठुड्डी की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लेते हुए धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0122', 'Barbell Wide Bench Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'barbell', 'strength', 'intermediate', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows slightly flared out.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़ी पकड़ से पकड़ें।","बारबेल को रैक से उठाएं और अपनी बाहों को पूरी तरह फैलाकर सीधे अपनी छाती के ऊपर पकड़ें।","अपनी कोहनियों को थोड़ा बाहर की ओर रखते हुए बारबेल को धीरे-धीरे अपनी छाती की ओर नीचे लाएँ।","जब बारबेल आपकी छाती को छू ले तो एक पल के लिए रुकें, फिर उसे वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Wide-Grip_Barbell_Bench_Press/0.jpg","Wide-Grip_Barbell_Bench_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1258', 'Barbell Wide Reverse Grip Bench Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'barbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","बारबेल को कंधे की चौड़ाई से थोड़ा चौड़ा, चौड़ी रिवर्स ग्रिप से पकड़ें।","बारबेल को रैक से उठाएं और अपनी बाहों को पूरी तरह फैलाकर सीधे अपनी छाती के ऊपर पकड़ें।","अपनी कोहनियों को अंदर की ओर और अपनी कलाइयों को सीधा रखते हुए, बारबेल को धीरे-धीरे अपनी छाती की ओर नीचे लाएँ।","जब बारबेल आपकी छाती को छू ले तो एक पल के लिए रुकें, फिर उसे वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0124', 'Barbell Wide Squat', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'barbell', 'strength', NULL, '["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अधिक चौड़ा करके खड़े रहें, पैर की उंगलियां थोड़ी बाहर की ओर हों।","बारबेल को अपनी ऊपरी पीठ पर पकड़ें, इसे अपने जाल या पीछे के डेल्टा पर टिकाएं।","अपने कोर को संलग्न करें और अपनी छाती को ऊपर रखें क्योंकि आप अपने शरीर को स्क्वाट में नीचे लाते हैं, अपने कूल्हों को पीछे धकेलते हैं और अपने घुटनों को मोड़ते हैं।","तब तक नीचे जाएँ जब तक आपकी जाँघें ज़मीन के समानांतर न हो जाएँ, या जितना नीचे आप आराम से जा सकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0123', 'Barbell Wide-Grip Upright Row', 'shoulders', 'delts', '["traps","biceps"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े हो जाएं और बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से ज्यादा चौड़े हों।","बारबेल को अपनी जाँघों के सामने लटका दें, बाहें पूरी तरह फैली हुई हों।","अपनी पीठ को सीधा रखते हुए, सांस छोड़ें और बारबेल को अपनी कोहनियों की मदद से सीधे अपनी ठुड्डी की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0126', 'Barbell Wrist Curl', 'lower arms', 'forearms', '["biceps","brachialis"]', 'barbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, holding a barbell with an underhand grip.","Allow the barbell to roll down to your fingertips, keeping your wrists straight.","Slowly curl the barbell up towards your forearms by flexing your wrists.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने अग्रभागों को अपनी जाँघों पर टिकाकर एक बेंच पर बैठें, एक बारबेल को हाथ से पकड़कर रखें।","अपनी कलाइयों को सीधा रखते हुए बारबेल को अपनी उंगलियों तक लुढ़कने दें।","अपनी कलाइयों को मोड़कर धीरे-धीरे बारबेल को अपनी बांहों की ओर ऊपर की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0125', 'Barbell Wrist Curl v. 2', 'lower arms', 'forearms', '["biceps","brachialis"]', 'barbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and your knees bent.","Hold a barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the barbell towards your forearms.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को मोड़कर एक बेंच पर बैठें।","बारबेल को अंडरहैंड ग्रिप से पकड़ें, हथेलियाँ ऊपर की ओर हों और आपके हाथ कंधे की चौड़ाई से अलग हों।","अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ, जिससे आपकी कलाइयाँ किनारे से लटक जाएँ।","धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, बारबेल को अपने अग्रबाहुओं की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0127', 'Barbell Zercher Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves","core"]', 'barbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability.","Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Keep your knees in line with your toes and your weight in your heels.","Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और पंजों को थोड़ा बाहर की ओर करके खड़े हो जाएं।","स्थिरता के लिए अपने हाथों से बारबेल को अपनी कोहनियों के मोड़ से पकड़ें।","अपने कोर को संलग्न करें और अपने कूल्हों को पीछे की ओर झुकाते हुए स्क्वाट स्थिति में आते समय अपनी छाती को ऊपर उठाएं।","अपने घुटनों को अपने पंजों की सीध में रखें और अपना वजन अपनी एड़ियों पर रखें।","स्क्वाट के निचले हिस्से में एक क्षण के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3212', 'Basic Toe Touch (Male)', 'upper legs', 'glutes', '["hamstrings","calves"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your arms by your sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with your hands, keeping your legs as straight as possible.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और अपनी बांहों को बगल में रखकर खड़े हो जाएं।","अपनी पीठ सीधी और घुटने थोड़े मुड़े हुए रखते हुए कमर के बल आगे की ओर झुकें।","अपने पैरों को जितना संभव हो सके सीधा रखते हुए, अपने हाथों को अपने पैर की उंगलियों तक पहुंचाएं।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0128', 'Battling Ropes', 'shoulders', 'delts', '["forearms","core"]', 'rope', 'strength', NULL, '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold one end of the rope in each hand, with your palms facing each other.","Raise your arms to shoulder height, keeping your elbows slightly bent.","Begin making alternating waves with the ropes by rapidly raising and lowering each arm.","Continue for the desired duration or number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","अपनी हथेलियों को एक-दूसरे के सामने रखते हुए, प्रत्येक हाथ में रस्सी का एक सिरा पकड़ें।","अपनी कोहनियों को थोड़ा मुड़ा हुआ रखते हुए, अपनी भुजाओं को कंधे की ऊँचाई तक उठाएँ।","प्रत्येक हाथ को तेजी से ऊपर और नीचे करके रस्सियों से बारी-बारी तरंगें बनाना शुरू करें।","वांछित अवधि या दोहराव की संख्या तक जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3360', 'Bear Crawl', 'cardio', 'cardiovascular system', '["core","shoulders","triceps"]', 'body weight', 'cardio', NULL, '["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Lift your knees slightly off the ground, keeping your back flat and your core engaged.","Move your right hand and left foot forward simultaneously, followed by your left hand and right foot.","Continue crawling forward, alternating your hand and foot movements.","Maintain a steady pace and keep your core tight throughout the exercise.","Continue for the desired distance or time."]', '["अपने हाथों को सीधे अपने कंधों के नीचे और अपने घुटनों को सीधे अपने कूल्हों के नीचे रखकर चारों तरफ से शुरुआत करें।","अपने घुटनों को ज़मीन से थोड़ा ऊपर उठाएं, अपनी पीठ को सपाट रखें और अपने कोर को व्यस्त रखें।","अपने दाहिने हाथ और बाएं पैर को एक साथ आगे बढ़ाएं, उसके बाद अपने बाएं हाथ और दाहिने पैर को आगे बढ़ाएं।","अपने हाथ और पैर की गतिविधियों को बारी-बारी से रेंगते हुए आगे बढ़ना जारी रखें।","एक स्थिर गति बनाए रखें और पूरे अभ्यास के दौरान अपने कोर को टाइट रखें।","वांछित दूरी या समय तक जारी रखें।"]', NULL, 7.5, 'time', 0, 'opengym', 1),
('og-1259', 'Behind Head Chest Stretch', 'chest', 'pectorals', '["shoulders","triceps"]', 'assisted', 'strength', NULL, '["Stand tall with your feet shoulder-width apart.","Interlace your fingers behind your head with your elbows pointing outwards.","Slowly squeeze your shoulder blades together and push your chest forward.","Hold the stretch for 15-30 seconds.","Release the stretch and repeat as desired."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े रहें।","अपनी कोहनियों को बाहर की ओर रखते हुए अपनी उंगलियों को अपने सिर के पीछे फंसा लें।","धीरे-धीरे अपने कंधे के ब्लेड को एक साथ दबाएं और अपनी छाती को आगे की ओर धकेलें।","15-30 सेकंड तक खिंचाव बनाए रखें।","खिंचाव छोड़ें और इच्छानुसार दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0129', 'Bench Dip (Knees Bent)', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', NULL, '["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["किसी बेंच या कुर्सी के किनारे पर अपने हाथों से अपने कूल्हों के बगल वाले किनारे को पकड़कर बैठें।","अपने बट को बेंच से स्लाइड करें और अपने पैरों को अपने सामने सीधा करें, अपनी एड़ियों को ज़मीन पर रखें।","अपनी कोहनियों को मोड़ें और अपने शरीर को ज़मीन की ओर नीचे करें, अपनी पीठ को बेंच के पास रखें।","नीचे एक पल के लिए रुकें, फिर अपने आप को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1399', 'Bench Dip On Floor', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', NULL, '["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["किसी बेंच या कुर्सी के किनारे पर बैठें और अपने हाथों से किनारे को पकड़ें, उंगलियाँ आगे की ओर हों।","अपने हाथों से अपने वजन को सहारा देते हुए, अपने बट को बेंच से स्लाइड करें।","अपनी कोहनियों को मोड़कर अपने शरीर को तब तक नीचे लाएँ जब तक कि आपकी ऊपरी भुजाएँ फर्श के समानांतर न हो जाएँ।","अपनी भुजाओं को सीधा करके स्वयं को प्रारंभिक स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0130', 'Bench Hip Extension', 'upper legs', 'glutes', '["hamstrings"]', 'body weight', 'strength', NULL, '["Sit on a bench with your back against the bench and your feet flat on the ground.","Place your hands on the bench for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपनी पीठ बेंच से सटाकर और अपने पैरों को ज़मीन पर सपाट करके बैठें।","समर्थन के लिए अपने हाथों को बेंच पर रखें।","अपने ग्लूट्स और हैमस्ट्रिंग को संलग्न करें, फिर अपने कूल्हों को बेंच से तब तक उठाएं जब तक कि आपका शरीर आपके घुटनों से आपके कंधों तक एक सीधी रेखा न बना ले।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3019', 'Bench Pull-Ups', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Position yourself under a bar or a sturdy horizontal surface that is at chest height.","Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your body straight.","Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.","Continue pulling until your chin is above the bar or surface.","Lower yourself back down to the starting position with control.","Repeat for the desired number of repetitions."]', '["अपने आप को एक पट्टी या एक मजबूत क्षैतिज सतह के नीचे रखें जो छाती की ऊंचाई पर हो।","बार या सतह को कंधे की चौड़ाई से थोड़ी अधिक चौड़ी पकड़ से पकड़ें।","अपनी बाहों को पूरी तरह फैलाकर और अपने शरीर को सीधा करके लटकें।","अपने कंधे के ब्लेड को एक साथ निचोड़कर और अपनी कोहनियों को मोड़कर अपनी छाती को बार या सतह की ओर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी बार या सतह से ऊपर न आ जाए।","नियंत्रण के साथ अपने आप को वापस प्रारंभिक स्थिति में ले आएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3639', 'Bent Knee Lying Twist (Male)', 'upper legs', 'glutes', '["obliques","hip flexors"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms out to the sides, perpendicular to your body.","Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees.","Pause for a moment, then engage your core and slowly lift your knees back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपनी भुजाओं को अपने शरीर के लंबवत भुजाओं तक फैलाएँ।","अपने घुटनों को एक साथ रखते हुए, उन्हें धीरे-धीरे एक तरफ नीचे करें, अपने घुटनों से जमीन को छूने का लक्ष्य रखें।","एक पल के लिए रुकें, फिर अपने कोर को संलग्न करें और धीरे-धीरे अपने घुटनों को वापस प्रारंभिक स्थिति में उठाएं।","इस क्रिया को दूसरी ओर भी दोहराएँ।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1770', 'Biceps Leg Concentration Curl', 'upper arms', 'biceps', '["forearms"]', 'body weight', 'strength', NULL, '["Sit on a bench with your legs spread apart and your feet flat on the ground.","Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.","With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को फैलाकर एक बेंच पर बैठें और आपके पैर जमीन पर सपाट हों।","एक हाथ में डम्बल पकड़ें और अपनी कोहनी को अपनी जांघ के अंदर, घुटने के ठीक ऊपर रखें।","अपनी हथेली को ऊपर की ओर रखते हुए, अपनी ऊपरी भुजा को स्थिर रखते हुए डम्बल को अपने कंधे की ओर मोड़ें।","अपने बाइसेप्स को मूवमेंट के शीर्ष पर निचोड़ें, फिर धीरे-धीरे डंबल को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0139', 'Biceps Narrow Pull-Ups', 'upper arms', 'biceps', '["forearms","shoulders"]', 'body weight', 'strength', NULL, '["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी हथेलियों को अपनी ओर रखते हुए और अपने हाथों को कंधे की चौड़ाई से अलग रखते हुए पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने शरीर को ऊपर उठाने के लिए अपने बाइसेप्स का उपयोग करने पर ध्यान केंद्रित करते हुए, अपने आप को बार की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने आप को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0140', 'Biceps Pull-Up', 'upper arms', 'biceps', '["forearms","shoulders"]', 'body weight', 'strength', NULL, '["Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.","Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar.","Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी हथेलियों को आपसे दूर की ओर और हाथों को कंधे की चौड़ाई से अलग रखते हुए पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपनी कोहनियों को मोड़कर, अपनी छाती को बार की ओर लाकर अपने आप को ऊपर खींचें।","गति के शीर्ष पर रुकें, फिर धीरे-धीरे अपने आप को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0137', 'Body-Up', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', 'intermediate', '["Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.","Extend your legs out in front of you, keeping your heels on the ground and your body straight.","Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.","Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को किसी ऊंची सतह, जैसे कि बेंच या समानांतर सलाखों पर रखकर शुरुआत करें, जिसमें आपकी हथेलियाँ नीचे की ओर हों और उंगलियाँ आगे की ओर हों।","अपने पैरों को अपने सामने फैलाएं, अपनी एड़ियों को ज़मीन पर और अपने शरीर को सीधा रखें।","अपनी कोहनियों को मोड़कर अपने शरीर को नीचे लाएँ, उन्हें अपनी भुजाओं के पास रखें, जब तक कि आपकी ऊपरी भुजाएँ ज़मीन के समानांतर न हो जाएँ।","एक पल के लिए रुकें, फिर अपनी हथेलियों से धक्का देकर अपनी भुजाओं को सीधा करें और अपने शरीर को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Body-Up/0.jpg","Body-Up/1.jpg"]', 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-3543', 'Bodyweight Drop Jump Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump up explosively, extending your hips, knees, and ankles.","While in mid-air, quickly bring your feet together.","Land softly on the balls of your feet and immediately drop back into a squat position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को स्क्वाट स्थिति में लाएँ।","अपने कूल्हों, घुटनों और टखनों को फैलाते हुए विस्फोटक तरीके से ऊपर कूदें।","हवा के बीच में रहते हुए, जल्दी से अपने पैरों को एक साथ लाएं।","अपने पैरों की उंगलियों पर धीरे से उतरें और तुरंत वापस बैठने की स्थिति में आ जाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3544', 'Bodyweight Incline Side Plank', 'waist', 'abs', '["obliques","shoulders"]', 'body weight', 'strength', NULL, '["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the ground and repeat on the other side."]', '["अपने पैरों को फैलाकर और एक दूसरे के ऊपर रखकर अपनी तरफ लेटकर शुरुआत करें।","अपनी कोहनी को 90 डिग्री के कोण पर मोड़ते हुए अपने अग्रबाहु को सीधे अपने कंधे के नीचे जमीन पर रखें।","अपने कोर को संलग्न करें और अपने कूल्हों को जमीन से ऊपर उठाएं, जिससे आपके सिर से आपके पैरों तक एक सीधी रेखा बन जाए।","वांछित समय तक इस स्थिति में रहें।","अपने कूल्हों को वापस ज़मीन पर टिकाएँ और दूसरी तरफ भी दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1771', 'Bodyweight Kneeling Triceps Extension', 'upper arms', 'triceps', '["shoulders","chest"]', 'body weight', 'strength', NULL, '["Kneel down on the ground with your knees hip-width apart.","Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward.","Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.","Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को कूल्हे-चौड़ाई से अलग रखते हुए जमीन पर बैठ जाएं।","अपने हाथों को अपने सामने ज़मीन पर रखें, कंधे की चौड़ाई से अलग, उंगलियाँ आगे की ओर हों।","अपने पैरों को अपने पीछे सीधा फैलाएं, अपने पैर की उंगलियों और हाथों पर संतुलन बनाते हुए, सिर से एड़ी तक एक सीधी रेखा बनाएं।","अपनी कोहनियों को मोड़ें और अपने ऊपरी शरीर को ज़मीन की ओर नीचे करें, अपनी कोहनियों को अपनी भुजाओं के पास रखें।","नीचे एक पल के लिए रुकें, फिर अपनी बाहों को सीधा करने के लिए अपने हाथों से धक्का दें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1769', 'Bodyweight Side Lying Biceps Curl', 'upper arms', 'biceps', '["forearms"]', 'body weight', 'strength', NULL, '["Lie on your side with your legs extended and your head supported by your arm.","Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपने सिर को अपनी बांह के सहारे रखते हुए अपनी तरफ लेटें।","अपनी ऊपरी भुजा को अपनी बगल में पकड़ें और अपनी कोहनी को मोड़कर अपने अग्रबाहु को अपने कंधे की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी बांह को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3168', 'Bodyweight Squatting Row', 'back', 'upper back', '["biceps","shoulders"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.","Lower your body into a squat position, keeping your back straight and your knees behind your toes.","From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपनी बाहों को फैलाकर किसी मजबूत वस्तु या सस्पेंशन ट्रेनर को पकड़ लें।","अपने शरीर को स्क्वाट स्थिति में लाएँ, अपनी पीठ सीधी रखें और अपने घुटनों को अपने पैर की उंगलियों के पीछे रखें।","स्क्वाट स्थिति से, अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, अपने शरीर को ऑब्जेक्ट या सस्पेंशन ट्रेनर की ओर ऊपर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3167', 'Bodyweight Squatting Row (With Towel)', 'back', 'upper back', '["biceps","shoulders"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.","Bend your knees and lower your body into a squat position, keeping your back straight and your chest up.","As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपनी हथेलियों को नीचे की ओर रखते हुए अपने सामने एक तौलिया रखें।","अपने घुटनों को मोड़ें और अपने शरीर को स्क्वाट स्थिति में लाएँ, अपनी पीठ सीधी रखें और अपनी छाती ऊपर रखें।","जैसे ही आप स्क्वाट में उतरते हैं, साथ ही अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, तौलिया को अपनी छाती की ओर खींचें।","स्क्वाट के निचले हिस्से में एक पल के लिए रुकें, फिर धीरे-धीरे अपनी बाहों को फैलाते हुए प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1373', 'Bodyweight Standing Calf Raise', 'lower legs', 'calves', '["ankles","feet"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart, toes pointing forward.","Place your hands on a wall or stable surface for balance.","Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां आगे की ओर हों।","संतुलन के लिए अपने हाथों को किसी दीवार या स्थिर सतह पर रखें।","धीरे-धीरे अपनी एड़ियों को जमीन से ऊपर उठाएं, अपने शरीर का वजन अपने पैरों की उंगलियों पर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3156', 'Bodyweight Standing Close-Grip One Arm Row', 'back', 'upper back', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, घुटने थोड़े मुड़े हुए हों और एक हाथ में तटस्थ पकड़ के साथ डंबल पकड़ें।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, कूल्हों के बल आगे की ओर झुकें।","अपनी कोहनी को अपने शरीर के पास रखते हुए और अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, डम्बल को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3158', 'Bodyweight Standing Close-Grip Row', 'back', 'upper back', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arms straight in front of you, gripping the bar or handles with a close grip.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, कमर के बल आगे की ओर झुकें।","अपनी बाहों को अपने सामने सीधा फैलाएं, बार या हैंडल को कसकर पकड़ें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बार या हैंडल को अपने शरीर की ओर खींचें।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3162', 'Bodyweight Standing One Arm Row', 'back', 'upper back', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Let the dumbbell hang straight down in front of you, with your arm fully extended.","Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your shoulder blades together at the top of the movement.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, घुटने थोड़े मुड़े हुए हों और एक हाथ में डंबल पकड़ लें।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, कूल्हों के बल आगे की ओर झुकें।","अपनी बांह को पूरी तरह फैलाकर डम्बल को अपने सामने सीधा लटका रहने दें।","अपनी कोहनी को अपने शरीर के पास रखते हुए डम्बल को अपनी छाती की ओर ऊपर खींचें।","आंदोलन के शीर्ष पर अपने कंधे के ब्लेड को एक साथ निचोड़ें।","डम्बल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3161', 'Bodyweight Standing One Arm Row (With Towel)', 'back', 'upper back', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, घुटने थोड़े मुड़े हुए हों और एक हाथ से तौलिया पकड़ लें।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, कूल्हों के बल आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, तौलिये को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे तौलिये को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3166', 'Bodyweight Standing Row', 'back', 'upper back', '["biceps","shoulders"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and knees slightly bent.","Grasp a bar or handles with an overhand grip, palms facing down.","Keep your back straight and core engaged.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","किसी बार या हैंडल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों।","अपनी पीठ सीधी और कोर व्यस्त रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बार या हैंडल को अपने शरीर की ओर खींचें।","गति के शीर्ष पर एक क्षण के लिए रुकें।","धीरे-धीरे अपनी भुजाओं को छोड़ें और वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3165', 'Bodyweight Standing Row (With Towel)', 'back', 'upper back', '["biceps","shoulders"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a towel in front of you with both hands.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों से अपने सामने एक तौलिया पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, तौलिये को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0138', 'Bottoms-Up', 'waist', 'abs', '["obliques","hip flexors"]', 'body weight', 'strength', 'beginner', '["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and bring them towards your chest, keeping your feet off the ground.","Engaging your abs, lift your hips off the ground, bringing your knees towards your head.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपनी भुजाओं को बगल में रखकर अपनी पीठ के बल सीधे लेट जाएँ।","अपने घुटनों को मोड़ें और उन्हें अपनी छाती की ओर लाएँ, अपने पैरों को ज़मीन से दूर रखें।","अपने पेट को जोड़ते हुए, अपने कूल्हों को ज़मीन से ऊपर उठाएं, अपने घुटनों को अपने सिर की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Bottoms_Up/0.jpg","Bottoms_Up/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1374', 'Box Jump Down With One Leg Stabilization', 'lower legs', 'calves', '["quadriceps","hamstrings","glutes"]', 'body weight', 'strength', NULL, '["Stand in front of a box or platform with your feet shoulder-width apart.","Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.","Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground.","Hold this position for a few seconds, engaging your calf muscles to maintain balance.","Slowly step down with the foot that is on the box, returning to the starting position.","Repeat the exercise with the other leg."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर किसी बॉक्स या प्लेटफॉर्म के सामने खड़े हो जाएं।","अपने घुटनों को मोड़ें और बॉक्स पर कूदें, एक पैर बॉक्स पर और दूसरा पैर किनारे से लटकाकर धीरे से उतरें।","अपने आप को बॉक्स पर रखे पैर से स्थिर करें, जबकि दूसरे पैर को ज़मीन से दूर रखें।","संतुलन बनाए रखने के लिए अपनी पिंडली की मांसपेशियों को शामिल करते हुए कुछ सेकंड के लिए इस स्थिति में रहें।","बॉक्स पर रखे पैर से धीरे-धीरे नीचे उतरें और प्रारंभिक स्थिति में लौट आएं।","दूसरे पैर से भी व्यायाम दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2466', 'Bridge - Mountain Climber (Cross Body)', 'waist', 'abs', '["glutes","quadriceps","hamstrings","shoulders","triceps"]', 'body weight', 'strength', NULL, '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow.","Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow.","Continue alternating sides, moving at a controlled pace.","Keep your hips level and avoid lifting your hips too high or sagging them too low.","Maintain a steady breathing pattern throughout the exercise.","Repeat for the desired number of repetitions."]', '["अपने हाथों को सीधे अपने कंधों के नीचे और अपने शरीर को एक सीधी रेखा में रखते हुए एक उच्च तख़्त स्थिति में शुरुआत करें।","अपने कोर को संलग्न करें और अपने दाहिने पैर को जमीन से ऊपर उठाएं, अपने दाहिने घुटने को अपनी बाईं कोहनी की ओर लाएं।","अपने दाहिने पैर को प्रारंभिक स्थिति में लौटाएँ और अपने बाएँ पैर से अपनी दाहिनी कोहनी की ओर इस क्रिया को दोहराएँ।","नियंत्रित गति से आगे बढ़ते हुए, पक्षों को बदलना जारी रखें।","अपने कूल्हों को समतल रखें और अपने कूल्हों को बहुत ऊपर उठाने या बहुत नीचे झुकाने से बचें।","पूरे अभ्यास के दौरान एक स्थिर श्वास पैटर्न बनाए रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1160', 'Burpee', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","calves","shoulders","chest"]', 'body weight', 'cardio', NULL, '["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you.","Kick your feet back into a push-up position.","Perform a push-up, keeping your body in a straight line.","Jump your feet back into the squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into a squat position to begin the next repetition."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए खड़े होकर शुरुआत करें।","अपने घुटनों को मोड़कर और अपने हाथों को अपने सामने फर्श पर रखकर अपने शरीर को स्क्वाट स्थिति में लाएँ।","अपने पैरों को वापस पुश-अप स्थिति में लाएँ।","अपने शरीर को सीधी रेखा में रखते हुए पुश-अप करें।","अपने पैरों को वापस स्क्वाट स्थिति में लाएँ।","अपनी भुजाओं को ऊपर की ओर पहुँचाते हुए, विस्फोटक तरीके से ऊपर उठें।","अगली पुनरावृत्ति शुरू करने के लिए धीरे से उतरें और तुरंत वापस बैठने की स्थिति में आ जाएँ।"]', NULL, 8, 'time', 0, 'opengym', 1),
('og-0870', 'Butt-Ups', 'waist', 'abs', '["hip flexors","lower back"]', 'body weight', 'strength', 'beginner', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides, palms facing down.","Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","At the top of the movement, squeeze your abs and pause for a moment.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को बगल में रखें, हथेलियाँ नीचे की ओर हों।","अपने पेट को संलग्न करते हुए, अपने पैरों को जमीन से ऊपर उठाएं, अपने घुटनों को अपनी छाती की ओर लाएं।","आंदोलन के शीर्ष पर, अपने पेट को निचोड़ें और एक पल के लिए रुकें।","धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Butt-Ups/0.jpg","Butt-Ups/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1494', 'Butterfly Yoga Pose', 'upper legs', 'adductors', '["hamstrings","groin"]', 'body weight', 'strength', NULL, '["Sit on the floor with your legs extended in front of you.","Bend your knees and bring the soles of your feet together, allowing your knees to fall out to the sides.","Hold onto your ankles or feet with your hands.","Sit up tall and lengthen your spine.","Gently press your knees down towards the floor, feeling a stretch in your inner thighs.","Hold this position for a few breaths.","To release, slowly bring your knees back up and extend your legs."]', '["अपने पैरों को अपने सामने फैलाकर फर्श पर बैठें।","अपने घुटनों को मोड़ें और अपने पैरों के तलवों को एक साथ लाएँ, जिससे आपके घुटने बगल की तरफ आ जाएँ।","अपने हाथों से अपने टखनों या पैरों को पकड़ें।","सीधे बैठें और अपनी रीढ़ को लंबा करें।","धीरे से अपने घुटनों को फर्श की ओर दबाएं, अपनी आंतरिक जांघों में खिंचाव महसूस करें।","कुछ सांसों के लिए इस स्थिति में रहें।","रिलीज़ करने के लिए, धीरे-धीरे अपने घुटनों को वापस ऊपर लाएँ और अपने पैरों को फैलाएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0148', 'Cable Alternate Shoulder Press', 'shoulders', 'delts', '["triceps","upper back"]', 'cable', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip.","Position your hands at shoulder height, with your palms facing forward.","Keep your core engaged and your back straight.","Press one handle up and forward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the handle back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और केबल मशीन के हैंडल को ओवरहैंड ग्रिप से पकड़ लें।","अपने हाथों को कंधे की ऊंचाई पर रखें, आपकी हथेलियाँ आगे की ओर हों।","अपने कोर को व्यस्त रखें और अपनी पीठ को सीधा रखें।","एक हैंडल को ऊपर और आगे की ओर दबाएं जब तक कि आपकी बांह पूरी तरह से विस्तारित न हो जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को वापस प्रारंभिक स्थिति में ले आएं।","दूसरे हाथ से दोहराएँ.","दोहराव की वांछित संख्या के लिए भुजाओं के बीच वैकल्पिक करें।"]', '["Alternating_Cable_Shoulder_Press/0.jpg","Alternating_Cable_Shoulder_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0149', 'Cable Alternate Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'cable', 'strength', NULL, '["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle.","Keep your upper arm stationary and extend your forearm backward, fully straightening your arm.","Pause for a moment, then slowly return to the starting position.","Repeat with your left arm.","Continue alternating arms for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","अपने दाहिने हाथ से केबल के हैंडल को पकड़ें और अपनी बांह ऊपर लाएं ताकि आपकी ऊपरी भुजा जमीन के समानांतर हो और आपकी कोहनी 90 डिग्री के कोण पर मुड़ी हुई हो।","अपनी ऊपरी बांह को स्थिर रखें और अपनी बांह को पूरी तरह सीधा करते हुए अपनी बांह को पीछे की ओर फैलाएं।","एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","अपने बाएँ हाथ से दोहराएँ।","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3235', 'Cable Assisted Inverse Leg Curl', 'upper legs', 'hamstrings', '["glutes","calves"]', 'cable', 'strength', NULL, '["Adjust the cable machine so that the ankle attachment is at the lowest setting.","Lie face down on the bench with your legs straight and the ankle attachment secured to your ankles.","Hold onto the handles of the bench for stability.","Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Pause for a moment at the top of the movement, squeezing your hamstrings.","Inhale and slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन को समायोजित करें ताकि टखने का लगाव सबसे कम सेटिंग पर हो।","अपने पैरों को सीधा रखते हुए और टखने को अपने टखनों से सुरक्षित रखते हुए बेंच पर मुंह के बल लेट जाएं।","स्थिरता के लिए बेंच के हैंडल को पकड़ें।","अपने ऊपरी शरीर को स्थिर रखते हुए, सांस छोड़ें और अपने घुटनों को मोड़ते हुए अपने पैरों को अपने ग्लूट्स की ओर मोड़ें।","अपनी हैमस्ट्रिंग को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0150', 'Cable Bar Lateral Pulldown', 'back', 'lats', '["biceps","rhomboids","rear deltoids"]', 'cable', 'strength', NULL, '["Adjust the cable pulley to a high position and attach a straight bar.","Sit facing the cable machine with your feet flat on the ground and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Pull the bar down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', '["केबल पुली को ऊंचे स्थान पर समायोजित करें और एक सीधी पट्टी संलग्न करें।","अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को थोड़ा मोड़कर केबल मशीन के सामने बैठें।","बार को ओवरहैंड पकड़ से पकड़ें, कंधे की चौड़ाई से थोड़ा अधिक चौड़ा।","थोड़ा पीछे झुकें और अपनी छाती को ऊपर रखें, अपनी पीठ के निचले हिस्से में हल्का सा आर्क बनाए रखें।","बार को अपनी छाती की ओर नीचे खींचें, अपनी कोहनियों से आगे बढ़ते हुए और अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए।","गति के निचले भाग पर एक पल के लिए रुकें, फिर धीरे-धीरे बार को प्रारंभिक स्थिति में लौटाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0151', 'Cable Bench Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'cable', 'strength', NULL, '["Adjust the cable machine to chest height and attach the handles.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and step forward to create tension in the cables.","Position your feet firmly on the ground and engage your core.","Bend your elbows and bring your hands to shoulder level, keeping your elbows at a 90-degree angle.","Push the handles forward, extending your arms fully in front of you.","Pause for a moment, then slowly reverse the movement, bringing your hands back to shoulder level.","Repeat for the desired number of repetitions."]', '["केबल मशीन को छाती की ऊंचाई तक समायोजित करें और हैंडल संलग्न करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और केबलों में तनाव पैदा करने के लिए आगे बढ़ें।","अपने पैरों को ज़मीन पर मजबूती से रखें और अपने कोर को संलग्न करें।","अपनी कोहनियों को मोड़ें और अपने हाथों को कंधे के स्तर पर लाएं, अपनी कोहनियों को 90 डिग्री के कोण पर रखें।","अपनी भुजाओं को अपने सामने पूरी तरह फैलाते हुए, हैंडल को आगे की ओर धकेलें।","एक पल के लिए रुकें, फिर धीरे-धीरे गति को उल्टा करें, अपने हाथों को कंधे के स्तर पर वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1630', 'Cable Close Grip Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["लो पुली केबल मशीन में एक सीधी पट्टी जोड़ें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर मशीन की ओर मुंह करके खड़े हो जाएं।","बार को अंडरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से अलग हों।","पूरे अभ्यास के दौरान अपनी कोहनियों को अपनी भुजाओं के पास और अपनी ऊपरी भुजाओं को स्थिर रखें।","सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए बार को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपनी बाहों को पूरी तरह फैलाते हुए बार को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1631', 'Cable Concentration Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Sit on a bench or chair with your feet flat on the floor and your knees slightly bent.","Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh.","Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps.","Pause for a moment at the top of the movement, then inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को फर्श पर सपाट करके और अपने घुटनों को थोड़ा मोड़कर एक बेंच या कुर्सी पर बैठें।","केबल के हैंडल को अंडरहैंड ग्रिप से पकड़ें और अपनी कोहनी को अपनी जांघ के अंदरूनी हिस्से पर टिकाएं।","अपनी ऊपरी बांह को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए केबल हैंडल को अपने कंधे की ओर मोड़ें।","गति के शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे केबल हैंडल को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0152', 'Cable Concentration Extension (On Knee)', 'upper arms', 'triceps', '["forearms"]', 'cable', 'strength', NULL, '["Sit on a bench or chair with your knees bent and feet flat on the ground.","Hold the cable handle with your right hand and place your elbow on the inside of your right knee.","Extend your arm fully, keeping your elbow stationary and close to your knee.","Pause for a moment at the top, then slowly lower your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट करके एक बेंच या कुर्सी पर बैठें।","केबल के हैंडल को अपने दाहिने हाथ से पकड़ें और अपनी कोहनी को अपने दाहिने घुटने के अंदर पर रखें।","अपनी बांह को पूरी तरह फैलाएं, अपनी कोहनी को स्थिर रखें और अपने घुटने के करीब रखें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने हाथ को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0153', 'Cable Cross-Over Lateral Pulldown', 'back', 'lats', '["biceps","rhomboids","rear deltoids"]', 'cable', 'strength', NULL, '["Attach a cable handle to each side of a cable machine at shoulder height.","Stand in the middle of the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and step back to create tension in the cables.","Lean forward slightly from the hips, keeping your back straight and your chest up.","Pull the handles down and across your body, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन के प्रत्येक तरफ कंधे की ऊंचाई पर एक केबल हैंडल संलग्न करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन के बीच में खड़े हो जाएं।","केबलों में तनाव पैदा करने के लिए हैंडल को ओवरहैंड ग्रिप से पकड़ें और पीछे हटें।","अपनी पीठ सीधी और छाती ऊपर रखते हुए, कूल्हों से थोड़ा आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को नीचे और अपने शरीर पर खींचें।","गति के निचले भाग पर एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0154', 'Cable Cross-Over Revers Fly', 'shoulders', 'delts', '["rhomboids","trapezius"]', 'cable', 'strength', NULL, '["Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.","Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart.","Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged.","With your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक लो पुली केबल में एक डी-हैंडल संलग्न करें और केबल क्रॉसओवर मशीन के बीच में खड़े हो जाएं।","हैंडल को उभरी हुई पकड़ से पकड़ें (हथेलियां नीचे की ओर हों) और अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एक कदम आगे बढ़ाएं।","अपने घुटनों को थोड़ा मोड़ें और कमर के बल आगे की ओर झुकें, अपनी पीठ सीधी रखें और अपने पेट को व्यस्त रखें।","अपनी भुजाओं को बगल की ओर फैलाकर और कोहनियों पर थोड़ा मुड़े हुए, सांस छोड़ें और अपने कंधे के ब्लेड को एक साथ निचोड़ें क्योंकि आप रिवर्स फ्लाई मोशन में केबल को पीछे और ऊपर की ओर खींचते हैं।","संकुचन के चरम पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0155', 'Cable Cross-Over Variation', 'chest', 'pectorals', '["deltoids","triceps"]', 'cable', 'strength', NULL, '["Adjust the cable pulleys to chest height.","Stand in the center of the cable machine with one foot in front of the other.","Grasp the handles with your palms facing down and your arms extended out to the sides.","Take a step forward, keeping your arms slightly bent.","With a slight bend in your elbows, bring your hands together in front of your chest.","Pause for a moment, then slowly return your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["केबल पुली को छाती की ऊंचाई तक समायोजित करें।","केबल मशीन के केंद्र में एक पैर दूसरे के सामने रखकर खड़े हो जाएं।","अपनी हथेलियों को नीचे की ओर रखते हुए और अपनी बाहों को बगल की ओर फैलाकर हैंडल को पकड़ें।","अपनी बाहों को थोड़ा झुकाते हुए एक कदम आगे बढ़ाएं।","अपनी कोहनियों को थोड़ा मोड़ते हुए, अपने हाथों को अपनी छाती के सामने एक साथ लाएँ।","एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को प्रारंभिक स्थिति में वापस लौटाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0868', 'Cable Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable attachment with an underhand grip, palms facing up.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","केबल अटैचमेंट को हाथ से पकड़ें, हथेलियाँ ऊपर की ओर हों।","अपनी कोहनियों को अपनी भुजाओं के पास रखें और अपनी ऊपरी भुजाओं को स्थिर रखें।","सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए केबल अटैचमेंट को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे केबल अटैचमेंट को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0157', 'Cable Deadlift', 'upper legs', 'glutes', '["hamstrings","quadriceps","lower back"]', 'cable', 'strength', 'beginner', '["Stand facing the cable machine with your feet shoulder-width apart.","Bend at the hips and knees, lowering your torso until your back is parallel to the ground.","Grasp the cable handles with an overhand grip, keeping your arms straight and your shoulders back.","Engage your glutes and hamstrings to lift the cable handles, extending your hips and standing up straight.","Pause for a moment at the top, then slowly lower the cable handles back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","कूल्हों और घुटनों पर झुकें, अपने धड़ को नीचे करें जब तक कि आपकी पीठ जमीन के समानांतर न हो जाए।","अपनी बाहों को सीधा और अपने कंधों को पीछे रखते हुए, केबल के हैंडल को ओवरहैंड ग्रिप से पकड़ें।","केबल के हैंडल को उठाने के लिए अपने ग्लूट्स और हैमस्ट्रिंग को शामिल करें, अपने कूल्हों को फैलाएं और सीधे खड़े हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केबल हैंडल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Cable_Deadlifts/0.jpg","Cable_Deadlifts/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0158', 'Cable Decline Fly', 'chest', 'pectorals', '["shoulders","triceps"]', 'cable', 'strength', NULL, '["Adjust the cable machine to a decline position.","Stand facing away from the machine with your feet shoulder-width apart.","Hold the handles with your palms facing forward and your arms extended straight out in front of you.","Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Pause for a moment at the fully extended position, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन को गिरावट की स्थिति में समायोजित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","अपनी हथेलियों को आगे की ओर रखते हुए हैंडल को पकड़ें और आपकी भुजाएँ आपके सामने सीधी फैली हुई हों।","अपनी कोहनियों को थोड़ा मोड़ते हुए, नियंत्रित गति में अपनी भुजाओं को बगल की ओर खोलें।","पूरी तरह विस्तारित स्थिति में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1260', 'Cable Decline One Arm Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'cable', 'strength', NULL, '["Adjust the cable machine to a decline position.","Stand facing away from the machine and grab the handle with one hand.","Position yourself with your back against the decline bench and your arm extended straight in front of you.","Bend your elbow and lower the handle towards your chest while keeping your upper arm stationary.","Pause for a moment at the bottom, then push the handle back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["केबल मशीन को गिरावट की स्थिति में समायोजित करें।","मशीन से दूर की ओर मुंह करके खड़े हो जाएं और एक हाथ से हैंडल को पकड़ लें।","अपने आप को डिक्लाइन बेंच के सामने अपनी पीठ के साथ रखें और आपका हाथ आपके सामने सीधा फैला हुआ हो।","अपनी कोहनी मोड़ें और अपने ऊपरी बांह को स्थिर रखते हुए हैंडल को अपनी छाती की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर हैंडल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1261', 'Cable Decline Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'cable', 'strength', NULL, '["Adjust the cable machine to a decline position.","Sit on the decline bench facing the cable machine.","Grasp the handles with an overhand grip and position them at chest level.","Keep your feet flat on the ground and your back firmly against the bench.","Exhale and push the handles away from your body, extending your arms fully.","Pause for a moment at the end of the movement, squeezing your chest muscles.","Inhale and slowly return the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन को गिरावट की स्थिति में समायोजित करें।","केबल मशीन के सामने डिक्लाइन बेंच पर बैठें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और उन्हें छाती के स्तर पर रखें।","अपने पैरों को ज़मीन पर सपाट रखें और अपनी पीठ को बेंच के सामने मजबूती से रखें।","सांस छोड़ें और अपनी बाहों को पूरी तरह फैलाते हुए हैंडल को अपने शरीर से दूर धकेलें।","आंदोलन के अंत में अपनी छाती की मांसपेशियों को निचोड़ते हुए एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे हैंडल को प्रारंभिक स्थिति में वापस लौटाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0159', 'Cable Decline Seated Wide-Grip Row', 'back', 'upper back', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Sit on the decline bench facing the cable machine with your feet securely placed on the footrests.","Grasp the cable attachment with a wide overhand grip, palms facing down.","Lean back slightly, keeping your back straight and your core engaged.","Pull the cable towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फ़ुटरेस्ट पर सुरक्षित रूप से रखकर केबल मशीन के सामने डिक्लाइन बेंच पर बैठें।","केबल अटैचमेंट को चौड़ी ओवरहैंड पकड़ से पकड़ें, हथेलियाँ नीचे की ओर हों।","अपनी पीठ सीधी और अपने कोर को व्यस्त रखते हुए थोड़ा पीछे झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, केबल को अपनी निचली छाती की ओर खींचें।","संकुचन के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे केबल को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1632', 'Cable Drag Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable attachment with an underhand grip, palms facing up, and arms fully extended.","Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders by contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","केबल अटैचमेंट को अंडरहैंड ग्रिप से पकड़ें, हथेलियाँ ऊपर की ओर हों और भुजाएँ पूरी तरह फैली हुई हों।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़कर केबल अटैचमेंट को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपनी बाहों को पूरी तरह फैलाते हुए केबल अटैचमेंट को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0160', 'Cable Floor Seated Wide-Grip Row', 'back', 'upper back', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Sit on the floor with your legs extended and your back straight.","Attach a cable handle to a low pulley and position the cable machine behind you.","Grasp the handle with a wide overhand grip, palms facing down.","Lean back slightly, keeping your back straight and your chest lifted.","Pull the handle towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपनी पीठ सीधी करके फर्श पर बैठें।","एक केबल हैंडल को निचली पुली से जोड़ें और केबल मशीन को अपने पीछे रखें।","हैंडल को चौड़ी ओवरहैंड पकड़ से पकड़ें, हथेलियाँ नीचे की ओर हों।","अपनी पीठ सीधी और छाती ऊपर उठाकर थोड़ा पीछे झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपनी कमर की ओर खींचें।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को वापस प्रारंभिक स्थिति में छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0161', 'Cable Forward Raise', 'shoulders', 'delts', '["triceps","forearms"]', 'cable', 'strength', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you.","Keeping your arms straight, raise the cable handle up to shoulder level.","Pause for a moment at the top, then slowly lower the cable handle back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","केबल के हैंडल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों और आपकी भुजाएँ आपके सामने पूरी तरह फैली हुई हों।","अपनी भुजाओं को सीधा रखते हुए, केबल के हैंडल को कंधे के स्तर तक उठाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केबल हैंडल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0162', 'Cable Front Raise', 'shoulders', 'delts', '["triceps","forearms"]', 'cable', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Keep your back straight and your core engaged.","Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Continue lifting until your arms are parallel to the floor.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और केबल के हैंडल को ओवरहैंड ग्रिप से पकड़ लें।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपनी बाहों को सीधा और हथेलियों को नीचे की ओर रखते हुए केबल के हैंडल को अपने सामने उठाएं।","तब तक उठाना जारी रखें जब तक आपकी भुजाएं फर्श के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केबल हैंडल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Front_Cable_Raise/0.jpg","Front_Cable_Raise/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0164', 'Cable Front Shoulder Raise', 'shoulders', 'delts', '["trapezius","biceps"]', 'cable', 'strength', NULL, '["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Keep your back straight and your core engaged.","Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Continue lifting until your arms are parallel to the floor.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और केबल के हैंडल को ओवरहैंड ग्रिप से पकड़ लें।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपनी बाहों को सीधा और हथेलियों को नीचे की ओर रखते हुए केबल के हैंडल को अपने सामने उठाएं।","तब तक उठाना जारी रखें जब तक आपकी भुजाएं फर्श के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केबल हैंडल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0165', 'Cable Hammer Curl (With Rope)', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Stand upright with your feet shoulder-width apart and a slight bend in your knees.","Hold the cable rope attachment with an underhand grip, palms facing each other, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the cable rope attachment until your biceps are fully contracted and the rope is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the cable rope attachment back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर सीधे खड़े हो जाएं।","केबल रस्सी के अटेचमेंट को हाथ से पकड़ें, हथेलियाँ एक-दूसरे के सामने हों और आपकी भुजाएँ पूरी तरह फैली हुई हों।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","केबल रस्सी के लगाव को तब तक ऊपर उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और रस्सी कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे केबल रस्सी के लगाव को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1722', 'Cable High Pulley Overhead Tricep Extension', 'upper arms', 'triceps', '["shoulders"]', 'cable', 'strength', NULL, '["Attach a rope to a high pulley and stand facing away from the machine.","Grasp the rope with both hands and extend your arms overhead.","Keep your elbows close to your head and your upper arms stationary.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["एक ऊंची चरखी में रस्सी बांधें और मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","दोनों हाथों से रस्सी को पकड़ें और अपनी बाहों को ऊपर की ओर फैलाएं।","अपनी कोहनियों को अपने सिर के पास रखें और अपनी ऊपरी भुजाओं को स्थिर रखें।","अपनी कोहनियों को मोड़कर धीरे-धीरे रस्सी को अपने सिर के पीछे नीचे लाएँ।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0167', 'Cable High Row (Kneeling)', 'back', 'upper back', '["biceps","shoulders"]', 'cable', 'strength', NULL, '["Attach a straight bar to a cable machine at chest height.","Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart.","Sit back on your heels, keeping your back straight and your core engaged.","Pull the bar towards your upper abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]', '["एक सीधी पट्टी को केबल मशीन से छाती की ऊंचाई पर जोड़ें।","केबल मशीन के सामने घुटने टेकें और हाथों को कंधे की चौड़ाई से अलग रखते हुए बार को ज़ोर से पकड़ें।","अपनी एड़ियों के बल बैठ जाएं, अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बार को अपने ऊपरी पेट की ओर खींचें।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बार को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0168', 'Cable Hip Adduction', 'upper legs', 'adductors', '["glutes","quadriceps"]', 'cable', 'strength', 'beginner', '["Attach the ankle cuff to your ankle and stand facing the cable machine.","Position yourself far enough away from the machine so that there is tension on the cable.","Place your hands on the machine for support.","Keeping your leg straight, slowly move your leg across your body towards the midline.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने टखने के कफ को अपने टखने से जोड़ें और केबल मशीन की ओर मुंह करके खड़े हो जाएं।","अपने आप को मशीन से इतनी दूर रखें कि केबल पर तनाव रहे।","समर्थन के लिए अपने हाथ मशीन पर रखें।","अपने पैर को सीधा रखते हुए, धीरे-धीरे अपने पैर को अपने शरीर के पार मध्य रेखा की ओर ले जाएं।","आंदोलन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Cable_Hip_Adduction/0.jpg","Cable_Hip_Adduction/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0169', 'Cable Incline Bench Press', 'chest', 'pectorals', '["deltoids","triceps"]', 'cable', 'strength', NULL, '["Adjust the bench to a 45-degree incline.","Attach the cable handles to the high pulleys.","Sit on the bench facing the cable machine with your feet flat on the ground.","Grasp the handles with an overhand grip and bring them to shoulder height.","Push the handles forward and upward until your arms are fully extended.","Pause for a moment, then slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["बेंच को 45 डिग्री के झुकाव पर समायोजित करें।","केबल के हैंडल को ऊंची पुली से जोड़ें।","अपने पैरों को ज़मीन पर सपाट करके केबल मशीन के सामने बेंच पर बैठें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और उन्हें कंधे की ऊंचाई पर लाएं।","जब तक आपकी बाहें पूरी तरह विस्तारित न हो जाएं तब तक हैंडल को आगे और ऊपर की ओर धकेलें।","एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1318', 'Cable Incline Bench Row', 'back', 'upper back', '["biceps","rear deltoids"]', 'cable', 'strength', NULL, '["Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley.","Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent.","Grasp the cable handle with an overhand grip and extend your arms fully in front of you.","Lean forward from your hips while keeping your back straight and your core engaged.","Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows.","Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["45-डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें और निचली चरखी पर एक केबल हैंडल संलग्न करें।","केबल मशीन के सामने वाली बेंच पर अपने पैरों को फर्श पर सपाट करके और अपने घुटनों को थोड़ा मोड़कर बैठें।","केबल हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी बाहों को अपने सामने पूरी तरह फैला लें।","अपनी पीठ सीधी और अपने कोर को व्यस्त रखते हुए अपने कूल्हों से आगे की ओर झुकें।","अपने कंधे के ब्लेड को पीछे खींचकर और अपनी कोहनियों को मोड़कर केबल के हैंडल को अपनी छाती की ओर खींचें।","आंदोलन के शीर्ष पर अपनी पीठ की मांसपेशियों को निचोड़ें, फिर धीरे-धीरे अपनी बाहों को प्रारंभिक स्थिति में वापस बढ़ाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0171', 'Cable Incline Fly', 'chest', 'pectorals', '["deltoids","triceps"]', 'cable', 'strength', NULL, '["Adjust the cable machine to a low position and attach the handles.","Sit on an incline bench with your back against the pad and feet flat on the floor.","Grasp the handles with an overhand grip and extend your arms straight out in front of you.","Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Pause for a moment at the fully extended position, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन को निचली स्थिति में समायोजित करें और हैंडल संलग्न करें।","एक झुकी हुई बेंच पर बैठें, अपनी पीठ पैड से सटाकर रखें और पैर फर्श पर सपाट रखें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी बाहों को अपने सामने सीधा फैलाएं।","अपनी कोहनियों को थोड़ा मोड़ते हुए, नियंत्रित गति में अपनी भुजाओं को बगल की ओर खोलें।","पूरी तरह विस्तारित स्थिति में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0170', 'Cable Incline Fly (On Stability Ball)', 'chest', 'pectorals', '["deltoids","triceps"]', 'cable', 'strength', NULL, '["Set up a stability ball at an incline angle.","Attach the cable handles to the high pulleys of a cable machine.","Sit on the stability ball facing away from the machine, with your feet firmly planted on the ground.","Grasp the cable handles with an overhand grip, palms facing forward.","Lean forward slightly, keeping your back straight and core engaged.","With a controlled motion, bring your arms out to the sides, keeping a slight bend in your elbows.","Continue the motion until your arms are parallel to the ground.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["एक झुकाव वाले कोण पर स्थिरता गेंद स्थापित करें।","केबल हैंडल को केबल मशीन की ऊंची पुली से जोड़ें।","स्टेबिलिटी बॉल पर मशीन से दूर की ओर मुंह करके बैठें, अपने पैरों को मजबूती से जमीन पर टिकाएं।","केबल के हैंडल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ आगे की ओर हों।","अपनी पीठ सीधी और कोर व्यस्त रखते हुए थोड़ा आगे झुकें।","नियंत्रित गति के साथ, अपनी कोहनियों को हल्का सा मोड़ते हुए, अपनी भुजाओं को बगल की ओर लाएँ।","जब तक आपकी भुजाएं जमीन के समानांतर न हो जाएं तब तक गति जारी रखें।","एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0172', 'Cable Incline Pushdown', 'back', 'lats', '["triceps","shoulders"]', 'cable', 'strength', 'beginner', '["Attach a straight bar to a high pulley cable machine.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Lean forward slightly and keep your back straight.","Pull the bar down towards your thighs by extending your elbows.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', '["हाई पुली केबल मशीन में एक सीधी पट्टी जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","बार को ओवरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","थोड़ा आगे की ओर झुकें और अपनी पीठ सीधी रखें।","अपनी कोहनियों को फैलाकर बार को अपनी जाँघों की ओर नीचे खींचें।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे बार को शुरुआती स्थिति में लौटा दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Cable_Incline_Pushdown/0.jpg","Cable_Incline_Pushdown/1.jpg"]', 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0173', 'Cable Incline Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'cable', 'strength', 'beginner', '["Adjust the cable machine to a low pulley position.","Attach a straight bar to the cable.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip and extend your arms straight overhead.","Lean forward slightly, keeping your back straight and core engaged.","Bend your elbows and lower the bar behind your head, keeping your upper arms close to your ears.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन को निचली चरखी स्थिति में समायोजित करें।","केबल से एक सीधी पट्टी जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","बार को ओवरहैंड ग्रिप से पकड़ें और अपनी भुजाओं को सीधा ऊपर की ओर फैलाएँ।","अपनी पीठ सीधी और कोर व्यस्त रखते हुए थोड़ा आगे झुकें।","अपनी कोहनियों को मोड़ें और बार को अपने सिर के पीछे नीचे करें, अपनी ऊपरी भुजाओं को अपने कानों के पास रखें।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Cable_Incline_Triceps_Extension/0.jpg","Cable_Incline_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0174', 'Cable Judo Flip', 'waist', 'abs', '["obliques","shoulders"]', 'cable', 'strength', 'beginner', '["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with both hands at chest level, palms facing down.","Engage your core and rotate your torso to the right, pulling the cable across your body.","As you rotate, pivot your back foot and allow your hips to rotate naturally.","Extend your arms fully and finish the movement by flipping the cable handle over your shoulder.","Return to the starting position by reversing the movement, rotating your torso back to the center.","Repeat the movement on the opposite side.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","केबल के हैंडल को दोनों हाथों से छाती के स्तर पर पकड़ें, हथेलियाँ नीचे की ओर हों।","अपने कोर को संलग्न करें और अपने धड़ को दाईं ओर घुमाएं, केबल को अपने शरीर पर खींचें।","जैसे ही आप घूमते हैं, अपने पिछले पैर को मोड़ें और अपने कूल्हों को स्वाभाविक रूप से घूमने दें।","अपनी बाहों को पूरी तरह फैलाएं और केबल के हैंडल को अपने कंधे पर घुमाकर गति समाप्त करें।","अपने धड़ को वापस केंद्र की ओर घुमाते हुए, गति को उलट कर प्रारंभिक स्थिति में लौट आएं।","विपरीत दिशा में भी यही क्रिया दोहराएँ।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', '["Cable_Judo_Flip/0.jpg","Cable_Judo_Flip/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0860', 'Cable Kickback', 'upper arms', 'triceps', '["shoulders"]', 'cable', 'strength', NULL, '["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable handle with your right hand and step back to create tension in the cable.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Keep your upper arm close to your body and your elbow bent at a 90-degree angle.","Extend your forearm backward, straightening your arm fully.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","अपने दाहिने हाथ से केबल के हैंडल को पकड़ें और केबल में तनाव पैदा करने के लिए पीछे हटें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी ऊपरी भुजा को अपने शरीर के पास रखें और अपनी कोहनी को 90 डिग्री के कोण पर मोड़ें।","अपनी बांह को पूरी तरह सीधा करते हुए, अपनी बांह को पीछे की ओर फैलाएं।","एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0175', 'Cable Kneeling Crunch', 'waist', 'abs', '["obliques"]', 'cable', 'strength', NULL, '["Attach a rope handle to a high pulley and kneel down facing away from the machine.","Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.","Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["एक ऊंची चरखी में रस्सी का हैंडल जोड़ें और मशीन से दूर की ओर मुंह करके घुटने टेकें।","रस्सी के हैंडल को दोनों हाथों से पकड़ें और इसे अपने सिर के पीछे रखें, अपनी कोहनियों को बगल की ओर रखें।","अपने कूल्हों को स्थिर रखते हुए, अपनी कमर को मोड़ें और अपने धड़ को अपनी जांघों की ओर झुकाएँ।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3697', 'Cable Kneeling Rear Delt Row (With Rope) (Male)', 'shoulders', 'delts', '["trapezius","rhomboids","biceps"]', 'cable', 'strength', NULL, '["Attach a rope handle to a low cable pulley and kneel down facing the machine.","Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you.","Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.","Squeeze your shoulder blades together at the end of the movement and hold for a brief pause.","Slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["एक निचली केबल पुली में रस्सी का हैंडल जोड़ें और मशीन की ओर घुटने टेकें।","रस्सी को तटस्थ पकड़ से पकड़ें (हथेलियाँ एक दूसरे के सामने) और अपनी भुजाओं को पूरी तरह अपने सामने फैलाएँ।","अपनी पीठ को सीधा और कोर को व्यस्त रखते हुए, अपने कंधे के ब्लेड को पीछे खींचकर रस्सी को अपने शरीर की ओर खींचें।","आंदोलन के अंत में अपने कंधे के ब्लेड को एक साथ निचोड़ें और एक संक्षिप्त विराम के लिए रुकें।","धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0176', 'Cable Kneeling Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'cable', 'strength', 'intermediate', '["Attach a rope handle to a high pulley and kneel down facing the cable machine.","Grasp the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head.","Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Extend your forearms by contracting your triceps until your arms are fully extended.","Pause for a moment, then slowly return to the starting position by bending your elbows.","Repeat for the desired number of repetitions."]', '["एक ऊंची चरखी में रस्सी का हैंडल जोड़ें और केबल मशीन की ओर घुटने टेकें।","रस्सी को तटस्थ पकड़ से पकड़ें (हथेलियाँ एक-दूसरे के सामने) और अपने हाथों को अपने सिर के किनारों पर लाएँ।","पूरे अभ्यास के दौरान अपनी कोहनियों को अपने सिर के पास और अपनी ऊपरी भुजाओं को स्थिर रखें।","अपने ट्राइसेप्स को सिकोड़कर अपने अग्रबाहुओं को तब तक फैलाएँ जब तक कि आपकी भुजाएँ पूरी तरह विस्तारित न हो जाएँ।","एक पल के लिए रुकें, फिर धीरे-धीरे अपनी कोहनियों को मोड़कर प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Kneeling_Cable_Triceps_Extension/0.jpg","Kneeling_Cable_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-2330', 'Cable Lat Pulldown Full Range Of Motion', 'back', 'lats', '["biceps","rhomboids","rear deltoids"]', 'cable', 'strength', NULL, '["Sit on the lat pulldown machine with your knees positioned under the pads.","Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को पैड के नीचे रखकर लैट पुलडाउन मशीन पर बैठें।","केबल बार को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","थोड़ा पीछे झुकें और अपनी छाती को ऊपर रखें, अपनी पीठ के निचले हिस्से में हल्का सा आर्क बनाए रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बार को अपनी ऊपरी छाती की ओर नीचे खींचें।","गति के निचले भाग पर एक पल के लिए रुकें, फिर धीरे-धीरे बार को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0177', 'Cable Lateral Pulldown (With Rope Attachment)', 'back', 'lats', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Attach a rope attachment to the cable machine at a high position.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing each other.","Keep your back straight and lean slightly back.","Pull the rope down towards your sides, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement.","Slowly release the tension and allow the rope to return to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन में ऊंचे स्थान पर रस्सी का अटैचमेंट लगाएं।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","रस्सी को ऊपरी पकड़ से पकड़ें, हथेलियाँ एक-दूसरे के सामने हों।","अपनी पीठ सीधी रखें और थोड़ा पीछे झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, रस्सी को अपनी तरफ नीचे खींचें।","आंदोलन के निचले भाग पर एक पल के लिए रुकें।","धीरे-धीरे तनाव छोड़ें और रस्सी को प्रारंभिक स्थिति में लौटने दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2616', 'Cable Lateral Pulldown With V-Bar', 'back', 'lats', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip.","Adjust the knee pad so that your thighs are secured under it.","Keep your back straight and lean back slightly.","Pull the v-bar down towards your upper chest while keeping your elbows close to your body.","Squeeze your back muscles at the bottom of the movement.","Slowly return the v-bar to the starting position and repeat for the desired number of repetitions."]', '["केबल पुलडाउन मशीन पर बैठें और वी-बार अटैचमेंट को ओवरहैंड ग्रिप से पकड़ें।","घुटने के पैड को समायोजित करें ताकि आपकी जांघें इसके नीचे सुरक्षित रहें।","अपनी पीठ सीधी रखें और थोड़ा पीछे झुकें।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए वी-बार को अपनी ऊपरी छाती की ओर नीचे खींचें।","आंदोलन के निचले भाग में अपनी पीठ की मांसपेशियों को निचोड़ें।","धीरे-धीरे वी-बार को शुरुआती स्थिति में लौटाएं और वांछित संख्या में दोहराव के लिए दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0178', 'Cable Lateral Raise', 'shoulders', 'delts', '["traps","triceps"]', 'cable', 'strength', NULL, '["Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip.","Keep your arms straight and your core engaged.","Raise your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और केबल के हैंडल को ओवरहैंड ग्रिप से पकड़ लें।","अपनी बाहों को सीधा रखें और अपने कोर को व्यस्त रखें।","अपनी भुजाओं को बगल की ओर तब तक उठाएँ जब तक वे फर्श के समानांतर न हो जाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0179', 'Cable Low Fly', 'chest', 'pectorals', '["deltoids","triceps"]', 'cable', 'strength', NULL, '["Attach the handles to the low pulleys of a cable machine and select an appropriate weight.","Stand in the middle of the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the handles with an overhand grip and extend your arms out to the sides, keeping a slight bend in your elbows.","Maintaining control, slowly bring your arms forward in a sweeping motion, crossing them in front of your body.","Pause for a moment at the peak of the movement, feeling the stretch in your chest muscles.","Reverse the motion and slowly return your arms to the starting position, keeping tension on your chest muscles throughout.","Repeat for the desired number of repetitions."]', '["केबल मशीन की निचली पुली में हैंडल जोड़ें और उचित वजन चुनें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर मशीन के बीच में खड़े हो जाएं।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी भुजाओं को बगल की ओर फैलाएँ।","नियंत्रण बनाए रखते हुए, धीरे-धीरे अपनी भुजाओं को व्यापक गति में आगे लाएं, उन्हें अपने शरीर के सामने से पार करें।","गति के चरम पर अपनी छाती की मांसपेशियों में खिंचाव महसूस करते हुए एक पल के लिए रुकें।","गति को उल्टा करें और धीरे-धीरे अपनी छाती की मांसपेशियों पर तनाव बनाए रखते हुए अपनी भुजाओं को प्रारंभिक स्थिति में लौटाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0180', 'Cable Low Seated Row', 'back', 'upper back', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with an overhand grip, palms facing down.","Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फ़ुटरेस्ट पर सपाट करके और अपने घुटनों को थोड़ा मोड़कर मशीन पर बैठें।","हैंडल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों।","अपनी पीठ सीधी रखें और अपनी कोहनियों को हल्का सा मोड़ते हुए थोड़ा आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपने शरीर की ओर खींचें।","गति के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1634', 'Cable Lying Bicep Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Attach a straight bar to a low pulley cable machine.","Lie face up on a flat bench with your feet flat on the ground.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your sides.","Keeping your upper arms stationary, exhale and curl the bar up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["लो पुली केबल मशीन में एक सीधी पट्टी जोड़ें।","अपने पैरों को जमीन पर सपाट रखते हुए एक सपाट बेंच पर मुंह करके लेट जाएं।","बार को अंडरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से अलग हों।","अपनी कोहनियों को अपनी भुजाओं के पास रखते हुए, अपनी भुजाओं को पूरी तरह फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और बार को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपनी बाहों को पूरी तरह फैलाते हुए बार को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0182', 'Cable Lying Close-Grip Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Attach a straight bar to a low pulley cable machine.","Lie face up on a flat bench with your feet flat on the ground.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your sides.","Keeping your upper arms stationary, curl the bar towards your chest by contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["लो पुली केबल मशीन में एक सीधी पट्टी जोड़ें।","अपने पैरों को जमीन पर सपाट रखते हुए एक सपाट बेंच पर मुंह करके लेट जाएं।","बार को अंडरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से अलग हों।","अपनी कोहनियों को अपनी भुजाओं के पास रखते हुए, अपनी भुजाओं को पूरी तरह फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपने बाइसेप्स को सिकोड़कर बार को अपनी छाती की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बार को धीरे-धीरे प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0184', 'Cable Lying Extension Pullover (With Rope Attachment)', 'back', 'lats', '["triceps","shoulders"]', 'cable', 'strength', NULL, '["Attach a rope to a cable machine and set the pulley at the highest position.","Lie down on a bench with your head towards the cable machine.","Hold the rope with both hands and extend your arms straight up above your chest.","Keeping your arms straight, slowly lower the rope behind your head while maintaining control.","Pause for a moment at the bottom, then slowly raise the rope back to the starting position.","Repeat for the desired number of repetitions."]', '["एक केबल मशीन में एक रस्सी जोड़ें और चरखी को उच्चतम स्थान पर सेट करें।","केबल मशीन की ओर अपना सिर करके एक बेंच पर लेट जाएँ।","दोनों हाथों से रस्सी को पकड़ें और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी भुजाओं को सीधा रखते हुए, नियंत्रण बनाए रखते हुए धीरे-धीरे रस्सी को अपने सिर के पीछे नीचे करें।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे रस्सी को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0185', 'Cable Lying Fly', 'chest', 'pectorals', '["deltoids","triceps"]', 'cable', 'strength', NULL, '["Attach the handles to the cables and lie flat on a bench with your feet flat on the ground.","Hold the handles with your palms facing each other and your arms extended straight above your chest.","Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["केबलों के हैंडल जोड़ें और अपने पैरों को ज़मीन पर सपाट रखते हुए एक बेंच पर सीधे लेट जाएँ।","अपनी हथेलियों को एक-दूसरे के सामने रखते हुए हैंडल को पकड़ें और आपकी भुजाएँ सीधे आपकी छाती के ऊपर फैली हुई हों।","अपनी कोहनियों को थोड़ा मोड़ते हुए, अपनी भुजाओं को एक चौड़े चाप में बगल की ओर तब तक नीचे लाएँ जब तक आपको अपनी छाती में खिंचाव महसूस न हो।","एक पल के लिए रुकें, फिर अपनी बाहों को प्रारंभिक स्थिति में वापस लाने के लिए अपनी छाती की मांसपेशियों को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0186', 'Cable Lying Triceps Extension v. 2', 'upper arms', 'triceps', '["shoulders"]', 'cable', 'strength', NULL, '["Attach a rope handle to a low pulley cable machine.","Lie down on a flat bench facing up, with your head towards the cable machine.","Grasp the rope handle with both hands, palms facing each other, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the rope handle towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["लो पुली केबल मशीन में रस्सी का हैंडल जोड़ें।","एक सपाट बेंच पर ऊपर की ओर मुंह करके लेट जाएं, अपना सिर केबल मशीन की ओर रखें।","रस्सी के हैंडल को दोनों हाथों से पकड़ें, हथेलियाँ एक-दूसरे के सामने हों, और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे रस्सी के हैंडल को अपने माथे की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0188', 'Cable Middle Fly', 'chest', 'pectorals', '["deltoids","triceps"]', 'cable', 'strength', NULL, '["Attach cables to both sides of a cable machine at chest height.","Stand in the center of the machine with one foot slightly in front of the other.","Grasp the handles with an overhand grip and extend your arms out to the sides.","Keep a slight bend in your elbows and maintain a slight forward lean.","Engage your chest muscles and bring your arms forward in a sweeping motion.","Pause for a moment at the center, then slowly return your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन के दोनों किनारों पर छाती की ऊंचाई पर केबल जोड़ें।","मशीन के बीच में एक पैर दूसरे पैर से थोड़ा सा सामने रखकर खड़े हो जाएं।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी भुजाओं को बगल की ओर फैलाएँ।","अपनी कोहनियों को थोड़ा मोड़ें और थोड़ा आगे की ओर झुकें।","अपनी छाती की मांसपेशियों को शामिल करें और अपनी भुजाओं को व्यापक गति में आगे लाएँ।","केंद्र में एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को प्रारंभिक स्थिति में वापस लौटाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0189', 'Cable One Arm Bent Over Row', 'back', 'upper back', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Stand facing a cable machine with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the cable handle with one hand, palm facing inward, and extend your arm fully.","Pull the cable handle towards your body, keeping your elbow close to your side, until your hand reaches your lower chest.","Pause for a moment, then slowly extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","केबल के हैंडल को एक हाथ से पकड़ें, हथेली अंदर की ओर रखें और अपना हाथ पूरी तरह फैलाएँ।","केबल के हैंडल को अपने शरीर की ओर खींचें, अपनी कोहनी को अपने पास रखें, जब तक कि आपका हाथ आपकी छाती के निचले हिस्से तक न पहुंच जाए।","एक पल के लिए रुकें, फिर धीरे-धीरे अपना हाथ वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0190', 'Cable One Arm Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palm facing up.","Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","केबल के हैंडल को अंडरहैंड ग्रिप से पकड़ें, हथेली ऊपर की ओर।","अपनी कोहनी को अपनी बगल में रखें और धीरे-धीरे अपने अग्रभाग को अपने कंधे की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी बांह को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1262', 'Cable One Arm Decline Chest Fly', 'chest', 'pectorals', '["shoulders","triceps"]', 'cable', 'strength', NULL, '["Attach a D-handle to a low pulley cable machine and set the bench to a decline angle.","Lie down on the bench with your head towards the machine and grab the handle with your right hand.","Extend your arm straight up above your chest, keeping a slight bend in your elbow.","With a controlled motion, lower your arm out to the side until your hand is in line with your shoulder.","Pause for a moment, then reverse the motion and bring your arm back to the starting position.","Repeat for the desired number of repetitions, then switch to your left arm and repeat the exercise."]', '["एक लो पुली केबल मशीन में एक डी-हैंडल संलग्न करें और बेंच को एक गिरावट कोण पर सेट करें।","मशीन की ओर सिर करके बेंच पर लेट जाएं और अपने दाहिने हाथ से हैंडल को पकड़ लें।","अपनी बांह को अपनी छाती के ऊपर सीधा फैलाएं, अपनी कोहनी को थोड़ा मोड़ते हुए।","नियंत्रित गति के साथ, अपने हाथ को बगल की ओर नीचे करें जब तक कि आपका हाथ आपके कंधे की सीध में न आ जाए।","एक पल के लिए रुकें, फिर गति को उल्टा करें और अपने हाथ को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर अपने बाएं हाथ पर स्विच करें और व्यायाम दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1263', 'Cable One Arm Fly On Exercise Ball', 'chest', 'pectorals', '["deltoids","triceps"]', 'cable', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground.","Keep your elbow slightly bent and your palm facing forward.","Slowly bring your arm across your body, squeezing your chest muscles.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक व्यायाम बॉल पर बैठें।","एक हाथ में केबल का हैंडल पकड़ें और अपने हाथ को ज़मीन के समानांतर बगल की ओर फैलाएँ।","अपनी कोहनी को थोड़ा मोड़कर रखें और अपनी हथेली को आगे की ओर रखें।","अपनी छाती की मांसपेशियों को निचोड़ते हुए धीरे-धीरे अपने हाथ को अपने शरीर के पार लाएँ।","आंदोलन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1264', 'Cable One Arm Incline Fly On Exercise Ball', 'chest', 'pectorals', '["deltoids","triceps"]', 'cable', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your back against an incline bench.","Hold a cable handle in one hand with your arm extended and palm facing inward.","Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder.","Pause for a moment, then squeeze your chest muscles to bring your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपनी पीठ को एक झुकी हुई बेंच के सामने रखकर एक व्यायाम बॉल पर बैठें।","अपने हाथ को फैलाकर और हथेली को अंदर की ओर रखते हुए एक हाथ में केबल के हैंडल को पकड़ें।","अपनी कोहनी को थोड़ा मोड़ते हुए, धीरे-धीरे अपनी बांह को बगल की ओर नीचे लाएँ जब तक कि आपका हाथ आपके कंधे की सीध में न आ जाए।","एक पल के लिए रुकें, फिर अपनी बांह को प्रारंभिक स्थिति में वापस लाने के लिए अपनी छाती की मांसपेशियों को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1265', 'Cable One Arm Incline Press', 'chest', 'pectorals', '["deltoids","triceps"]', 'cable', 'strength', NULL, '["Adjust the cable machine to a low pulley position.","Sit on an incline bench facing away from the cable machine.","Grasp the handle with one hand and bring it up to shoulder height.","Position your feet firmly on the ground and maintain a stable position.","Press the handle forward and upward, extending your arm fully.","Pause for a moment at the top, then slowly lower the handle back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["केबल मशीन को निचली चरखी स्थिति में समायोजित करें।","केबल मशीन से दूर की ओर मुंह करके एक झुकी हुई बेंच पर बैठें।","एक हाथ से हैंडल को पकड़ें और इसे कंधे की ऊंचाई तक ले आएं।","अपने पैरों को ज़मीन पर मजबूती से रखें और स्थिर स्थिति बनाए रखें।","अपने हाथ को पूरी तरह फैलाते हुए हैंडल को आगे और ऊपर की ओर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1266', 'Cable One Arm Incline Press On Exercise Ball', 'chest', 'pectorals', '["shoulders","triceps"]', 'cable', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench.","Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent.","Press the cable handle forward and upward, extending your arm fully.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपनी पीठ को एक झुकी हुई बेंच पर टिकाकर एक व्यायाम बॉल पर बैठें।","एक हाथ में केबल हैंडल पकड़ें और अपनी बांह को कोहनी मोड़कर 90 डिग्री के कोण पर रखें।","अपने हाथ को पूरी तरह फैलाते हुए केबल हैंडल को आगे और ऊपर की ओर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केबल हैंडल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0191', 'Cable One Arm Lateral Bent-Over', 'chest', 'pectorals', '["deltoids","trapezius"]', 'cable', 'strength', NULL, '["Stand with your feet shoulder-width apart, facing a cable machine.","Grasp the handle with one hand and step back to create tension on the cable.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arm out to the side, parallel to the ground, with a slight bend in your elbow.","Slowly bring your arm back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions, then switch sides."]', '["केबल मशीन की ओर मुंह करके अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं।","एक हाथ से हैंडल को पकड़ें और केबल पर तनाव पैदा करने के लिए पीछे हटें।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, कमर के बल आगे की ओर झुकें।","अपनी कोहनी को थोड़ा मोड़ते हुए, अपनी भुजा को ज़मीन के समानांतर बगल की ओर फैलाएँ।","पूरे आंदोलन के दौरान नियंत्रण बनाए रखते हुए धीरे-धीरे अपने हाथ को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0192', 'Cable One Arm Lateral Raise', 'shoulders', 'delts', '["traps","triceps"]', 'cable', 'strength', NULL, '["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable.","Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["केबल मशीन की ओर मुंह करके अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं।","केबल के हैंडल को एक हाथ से पकड़ें, हथेली नीचे की ओर रखें और मशीन से इतनी दूर खड़े रहें कि केबल पर तनाव रहे।","अपनी भुजा सीधी रखें और धीरे-धीरे इसे बगल की ओर उठाएं जब तक कि यह जमीन के समानांतर न हो जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने हाथ को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1633', 'Cable One Arm Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Adjust the cable machine so that the preacher curl pad is at chest height.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip and position your upper arm against the preacher curl pad.","Keep your back straight and your core engaged.","Slowly curl the cable handle towards your shoulder, keeping your upper arm against the pad.","Pause for a moment at the top of the movement, squeezing your biceps.","Slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."]', '["केबल मशीन को समायोजित करें ताकि प्रीचर कर्ल पैड छाती की ऊंचाई पर हो।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","केबल के हैंडल को अंडरहैंड ग्रिप से पकड़ें और अपनी ऊपरी भुजा को प्रीचर कर्ल पैड के सामने रखें।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","धीरे-धीरे केबल के हैंडल को अपने कंधे की ओर मोड़ें, अपनी ऊपरी भुजा को पैड के सामने रखें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","धीरे-धीरे केबल हैंडल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।","हथियार बदलें और व्यायाम दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1267', 'Cable One Arm Press On Exercise Ball', 'chest', 'pectorals', '["shoulders","triceps"]', 'cable', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a cable handle in one hand and position your arm at chest height, elbow bent.","Place your other hand on your hip for stability.","Press the cable handle forward, extending your arm fully.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक व्यायाम बॉल पर बैठें।","एक हाथ में केबल का हैंडल पकड़ें और अपनी बांह को कोहनी मोड़कर छाती की ऊंचाई पर रखें।","स्थिरता के लिए अपना दूसरा हाथ अपने कूल्हे पर रखें।","अपने हाथ को पूरी तरह फैलाते हुए केबल हैंडल को आगे की ओर दबाएं।","एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3563', 'Cable One Arm Pulldown', 'back', 'lats', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Attach a single handle to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handle with an overhand grip and extend your arm fully.","Keep your back straight and your core engaged.","Pull the handle down towards your side while keeping your elbow close to your body.","Pause for a moment at the bottom of the movement, squeezing your lat muscle.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other arm."]', '["हाई पुली केबल मशीन में एक हैंडल जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी बांह को पूरी तरह फैलाएं।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपनी कोहनी को अपने शरीर के करीब रखते हुए हैंडल को अपनी तरफ नीचे खींचें।","अपनी अंडकोश की मांसपेशी को निचोड़ते हुए, आंदोलन के निचले भाग में एक पल के लिए रुकें।","धीरे-धीरे हैंडल को वापस प्रारंभिक स्थिति में छोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।","करवट बदलें और दूसरे हाथ से व्यायाम दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1635', 'Cable One Arm Reverse Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Adjust the cable machine so that the pulley is at the lowest position.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip and position your upper arm against the preacher bench pad.","Keep your back straight and your core engaged throughout the exercise.","Slowly curl your forearm towards your bicep, keeping your upper arm stationary against the pad.","Pause for a moment at the top of the movement, squeezing your bicep.","Slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."]', '["केबल मशीन को समायोजित करें ताकि चरखी सबसे निचले स्थान पर हो।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","केबल के हैंडल को अंडरहैंड ग्रिप से पकड़ें और अपनी ऊपरी भुजा को प्रीचर बेंच पैड के सामने रखें।","पूरे अभ्यास के दौरान अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","धीरे-धीरे अपने अग्रबाहु को अपने बाइसेप्स की ओर मोड़ें, अपनी ऊपरी भुजा को पैड के सामने स्थिर रखें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","धीरे-धीरे केबल हैंडल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।","हथियार बदलें और व्यायाम दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0193', 'Cable One Arm Straight Back High Row (Kneeling)', 'back', 'upper back', '["biceps","shoulders"]', 'cable', 'strength', NULL, '["Attach a handle to a cable machine at waist height.","Kneel down facing the cable machine and grab the handle with one hand.","Keep your back straight and your core engaged.","Pull the handle towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other arm."]', '["केबल मशीन में कमर की ऊंचाई पर एक हैंडल जोड़ें।","केबल मशीन के सामने घुटने टेकें और एक हाथ से हैंडल पकड़ें।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपनी छाती की ओर खींचें।","गति के शीर्ष पर एक क्षण के लिए रुकें।","धीरे-धीरे हैंडल को वापस प्रारंभिक स्थिति में छोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।","करवट बदलें और दूसरे हाथ से व्यायाम दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1723', 'Cable One Arm Tricep Pushdown', 'upper arms', 'triceps', '["forearms"]', 'cable', 'strength', NULL, '["Stand facing a cable machine with a straight bar attachment at chest height.","Grasp the bar with an overhand grip and step back to create tension in the cable.","Position your feet shoulder-width apart and slightly bend your knees.","Keep your back straight and core engaged throughout the exercise.","Start with your arm fully extended and perpendicular to the floor.","Keeping your upper arm stationary, exhale and push the bar down until your arm is fully extended.","Pause for a moment, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["छाती की ऊंचाई पर सीधी बार अटैचमेंट वाली केबल मशीन की ओर मुंह करके खड़े हो जाएं।","केबल में तनाव पैदा करने के लिए बार को ओवरहैंड ग्रिप से पकड़ें और पीछे हटें।","अपने पैरों को कंधे की चौड़ाई से अलग रखें और अपने घुटनों को थोड़ा मोड़ लें।","पूरे अभ्यास के दौरान अपनी पीठ सीधी रखें और मुख्य भाग को व्यस्त रखें।","अपने हाथ को पूरी तरह फैलाकर और फर्श से लंबवत रखकर शुरुआत करें।","अपनी ऊपरी बांह को स्थिर रखते हुए, सांस छोड़ें और बार को तब तक नीचे धकेलें जब तक कि आपकी बांह पूरी तरह विस्तारित न हो जाए।","एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1636', 'Cable Overhead Curl', 'upper arms', 'biceps', '["forearms","shoulders"]', 'cable', 'strength', 'intermediate', '["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the bar down towards your forehead, keeping your upper arms stationary.","Pause for a moment at the bottom of the movement, squeezing your biceps.","Inhale and slowly return the bar to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["हाई पुली केबल मशीन में एक सीधी पट्टी जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","बार को अंडरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से अलग हों।","अपनी कोहनियों को अपनी भुजाओं के पास रखें और अपनी ऊपरी भुजाओं को स्थिर रखें।","सांस छोड़ें और अपनी ऊपरी भुजाओं को स्थिर रखते हुए बार को अपने माथे की ओर नीचे की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के निचले भाग में एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपनी बाहों को पूरी तरह फैलाते हुए बार को प्रारंभिक स्थिति में लौटाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Overhead_Cable_Curl/0.jpg","Overhead_Cable_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1637', 'Cable Overhead Curl On Exercise Ball', 'upper arms', 'biceps', '["forearms","shoulders"]', 'cable', 'strength', NULL, '["Sit on an exercise ball and hold the cable handle with an underhand grip.","Extend your arms fully overhead, keeping your elbows close to your ears.","Slowly curl the cable down towards your forehead, keeping your upper arms stationary.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["एक्सरसाइज बॉल पर बैठें और केबल के हैंडल को हल्के से पकड़ें।","अपनी कोहनियों को अपने कानों के पास रखते हुए, अपनी भुजाओं को पूरी तरह ऊपर की ओर फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए धीरे-धीरे केबल को अपने माथे की ओर नीचे की ओर मोड़ें।","गति के निचले भाग पर एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0194', 'Cable Overhead Triceps Extension (Rope Attachment)', 'upper arms', 'triceps', '["shoulders"]', 'cable', 'strength', NULL, '["Attach a rope to a cable machine at a high position.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing each other, and bring your hands above your head.","Keep your upper arms close to your head and your elbows pointing forward.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["एक रस्सी को केबल मशीन से ऊँचे स्थान पर जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","रस्सी को दोनों हाथों से पकड़ें, हथेलियाँ एक-दूसरे के सामने हों, और अपने हाथों को अपने सिर के ऊपर लाएँ।","अपनी ऊपरी भुजाओं को अपने सिर के पास रखें और अपनी कोहनियों को आगे की ओर रखें।","अपनी कोहनियों को मोड़कर धीरे-धीरे रस्सी को अपने सिर के पीछे नीचे लाएँ।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1319', 'Cable Palm Rotational Row', 'back', 'upper back', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Attach a handle to a cable machine at waist height.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handle with an overhand grip, palms facing down.","Step back to create tension on the cable, keeping your back straight and knees slightly bent.","Pull the handle towards your body, rotating your palms to face upwards as you do so.","Squeeze your shoulder blades together at the end of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन में कमर की ऊंचाई पर एक हैंडल जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","हैंडल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों।","केबल पर तनाव पैदा करने के लिए पीछे हटें, अपनी पीठ सीधी रखें और घुटने थोड़े मुड़े हुए रहें।","हैंडल को अपने शरीर की ओर खींचें, ऐसा करते समय अपनी हथेलियों को ऊपर की ओर घुमाएँ।","आंदोलन के अंत में अपने कंधे के ब्लेड को एक साथ निचोड़ें।","धीरे-धीरे हैंडल को वापस प्रारंभिक स्थिति में छोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0195', 'Cable Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', 'beginner', '["Adjust the cable machine so that the preacher curl pad is at chest height.","Sit on the preacher curl bench and place your upper arms on the pad, gripping the cable attachment with an underhand grip.","Keep your back straight and your elbows tucked in at your sides.","Slowly curl the cable attachment up towards your shoulders, squeezing your biceps at the top of the movement.","Pause for a moment, then slowly lower the cable attachment back down to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन को समायोजित करें ताकि प्रीचर कर्ल पैड छाती की ऊंचाई पर हो।","प्रीचर कर्ल बेंच पर बैठें और अपनी ऊपरी भुजाओं को पैड पर रखें, केबल अटैचमेंट को अंडरहैंड ग्रिप से पकड़ें।","अपनी पीठ सीधी रखें और अपनी कोहनियाँ बगल में टिकी हुई हों।","धीरे-धीरे केबल अटैचमेंट को अपने कंधों की ओर घुमाएं, अपने बाइसेप्स को मूवमेंट के शीर्ष पर निचोड़ें।","एक पल के लिए रुकें, फिर धीरे-धीरे केबल अटैचमेंट को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Cable_Preacher_Curl/0.jpg","Cable_Preacher_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1268', 'Cable Press On Exercise Ball', 'chest', 'pectorals', '["shoulders","triceps"]', 'cable', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle.","Hold the cable handles at chest height with your palms facing down and your elbows bent.","Engage your core and press the cable handles forward until your arms are fully extended.","Pause for a moment, then slowly release the tension and bring the cable handles back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को 90 डिग्री के कोण पर रखकर एक व्यायाम बॉल पर बैठें।","अपनी हथेलियों को नीचे की ओर और अपनी कोहनियों को मोड़कर केबल के हैंडल को छाती की ऊंचाई पर पकड़ें।","अपने कोर को संलग्न करें और केबल के हैंडल को तब तक आगे की ओर दबाएं जब तक कि आपकी भुजाएं पूरी तरह से विस्तारित न हो जाएं।","एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और केबल हैंडल को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0196', 'Cable Pull Through (With Rope)', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'cable', 'strength', NULL, '["Stand facing away from the cable machine with your feet shoulder-width apart.","Grab the rope attachment with both hands and step forward, creating tension in the cable.","Bend at the hips and lower your upper body until it is parallel to the ground, keeping your back straight.","Engage your glutes and hamstrings to pull your body back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","रस्सी के लगाव को दोनों हाथों से पकड़ें और आगे बढ़ें, जिससे केबल में तनाव पैदा हो।","कूल्हों पर झुकें और अपने ऊपरी शरीर को तब तक नीचे करें जब तक कि वह जमीन के समानांतर न हो जाए, अपनी पीठ को सीधा रखें।","अपने शरीर को शुरुआती स्थिति में वापस खींचने के लिए अपने ग्लूट्स और हैमस्ट्रिंग को शामिल करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0198', 'Cable Pulldown', 'back', 'lats', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Adjust the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured.","Sit on the seat with your back straight and your feet flat on the ground.","Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and engage your core.","Pull the cable bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]', '["केबल पुलडाउन मशीन को समायोजित करें ताकि सीट आरामदायक ऊंचाई पर हो और घुटने का पैड सुरक्षित रहे।","अपनी पीठ सीधी करके सीट पर बैठें और आपके पैर ज़मीन पर सपाट हों।","केबल बार को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","थोड़ा पीछे झुकें और अपने कोर को संलग्न करें।","अपने कंधे के ब्लेड को एक साथ दबाते हुए, केबल बार को अपनी छाती की ओर नीचे खींचें।","गति के निचले भाग पर एक पल के लिए रुकें, फिर धीरे-धीरे बार को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-0197', 'Cable Pulldown (Pro Lat Bar)', 'back', 'lats', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor.","Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart.","Sit down and lean back slightly, keeping your chest up and your back straight.","Pull the bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई को समायोजित करें ताकि आपकी जांघें जमीन के समानांतर हों और आपके पैर फर्श पर सपाट हों।","लैट बार को ओवरहैंड ग्रिप से पकड़ें, जो कंधे की चौड़ाई से थोड़ा अधिक चौड़ा हो।","बैठ जाएं और अपनी छाती को ऊपर और पीठ को सीधा रखते हुए थोड़ा पीछे झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बार को अपनी छाती की ओर नीचे खींचें।","गति के निचले भाग पर एक क्षण के लिए रुकें, फिर धीरे-धीरे बार को प्रारंभिक स्थिति में वापस छोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1638', 'Cable Pulldown Bicep Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Attach a straight bar to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and slowly curl the bar down towards your thighs, keeping your wrists straight.","Pause for a moment at the bottom of the movement, squeezing your biceps.","Inhale and slowly return the bar to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["उच्चतम सेटिंग पर केबल मशीन में एक सीधी पट्टी संलग्न करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","बार को अंडरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से अलग हों।","अपनी कोहनियों को अपनी भुजाओं के पास रखें और अपनी ऊपरी भुजाओं को स्थिर रखें।","सांस छोड़ें और अपनी कलाइयों को सीधा रखते हुए बार को धीरे-धीरे अपनी जांघों की ओर नीचे की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के निचले भाग में एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपनी बाहों को पूरी तरह फैलाते हुए बार को प्रारंभिक स्थिति में लौटाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0201', 'Cable Pushdown', 'upper arms', 'triceps', '["forearms"]', 'cable', 'strength', NULL, '["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the bar with an overhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and push the bar down until your elbows are fully extended.","Pause for a moment, then inhale and slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', '["हाई पुली केबल मशीन में एक सीधी पट्टी जोड़ें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर मशीन की ओर मुंह करके खड़े हो जाएं।","हाथों को कंधे की चौड़ाई से अलग रखते हुए बार को ओवरहैंड पकड़ से पकड़ें।","अपनी कोहनियों को अपनी भुजाओं के पास रखें और अपनी ऊपरी भुजाओं को स्थिर रखें।","साँस छोड़ें और बार को तब तक नीचे धकेलें जब तक कि आपकी कोहनियाँ पूरी तरह विस्तारित न हो जाएँ।","एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे बार को शुरुआती स्थिति में लौटा दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-0199', 'Cable Pushdown (Straight Arm) v. 2', 'back', 'lats', '["triceps","shoulders"]', 'cable', 'strength', NULL, '["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.","Engage your core and keep your back straight as you exhale and push the bar down towards your thighs.","Pause for a moment at the bottom, then slowly return the bar to the starting position while inhaling.","Repeat for the desired number of repetitions."]', '["हाई पुली केबल मशीन में एक सीधी पट्टी जोड़ें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर मशीन की ओर मुंह करके खड़े हो जाएं।","अपनी बाहों को सीधा रखते हुए और अपनी हथेलियों को नीचे की ओर रखते हुए, बार को ओवरहैंड ग्रिप से पकड़ें।","अपने कोर को संलग्न करें और सांस छोड़ते हुए अपनी पीठ सीधी रखें और बार को अपनी जांघों की ओर नीचे धकेलें।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे सांस लेते हुए बार को शुरुआती स्थिति में लौटा दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0200', 'Cable Pushdown (With Rope Attachment)', 'upper arms', 'triceps', '["forearms"]', 'cable', 'strength', NULL, '["Attach a rope attachment to a high pulley on a cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the rope with an overhand grip, palms facing each other.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and push the rope downward by extending your elbows until your arms are fully extended.","Pause for a moment, then inhale and slowly return to the starting position by allowing your elbows to flex.","Repeat for the desired number of repetitions."]', '["एक केबल मशीन पर एक उच्च चरखी से रस्सी का लगाव जोड़ें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर मशीन की ओर मुंह करके खड़े हो जाएं।","रस्सी को ऊपरी पकड़ से पकड़ें, हथेलियाँ एक-दूसरे के सामने हों।","पूरे अभ्यास के दौरान अपनी कोहनियों को अपनी भुजाओं के पास और अपनी ऊपरी भुजाओं को स्थिर रखें।","सांस छोड़ें और अपनी कोहनियों को फैलाकर रस्सी को तब तक नीचे की ओर धकेलें जब तक कि आपकी बाहें पूरी तरह फैल न जाएं।","एक पल के लिए रुकें, फिर सांस लें और अपनी कोहनियों को मोड़कर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0202', 'Cable Rear Delt Row (Stirrups)', 'shoulders', 'delts', '["trapezius","rhomboids","biceps"]', 'cable', 'strength', NULL, '["Attach a stirrup handle to a low cable pulley and stand facing the machine.","Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","With your left arm extended and your palm facing down, pull the handle towards your chest by retracting your shoulder blade.","Pause for a moment at the top of the movement, squeezing your shoulder blade.","Slowly release the handle back to the starting position and repeat for the desired number of repetitions.","Switch sides and repeat the exercise with your right arm."]', '["एक निचली केबल पुली में रकाब का हैंडल जोड़ें और मशीन की ओर मुंह करके खड़े हो जाएं।","अपने बाएं हाथ से हैंडल को पकड़ें और अपने दाहिने पैर से एक कदम पीछे जाएं, अपने शरीर को थोड़ा कोण पर रखें।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपने बाएं हाथ को फैलाकर और अपनी हथेली को नीचे की ओर रखते हुए, अपने कंधे के ब्लेड को पीछे खींचकर हैंडल को अपनी छाती की ओर खींचें।","अपने कंधे के ब्लेड को निचोड़ते हुए, आंदोलन के शीर्ष पर एक पल के लिए रुकें।","धीरे-धीरे हैंडल को वापस प्रारंभिक स्थिति में छोड़ें और वांछित संख्या में दोहराव के लिए दोहराएं।","करवट बदलें और अपने दाहिने हाथ से व्यायाम दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0203', 'Cable Rear Delt Row (With Rope)', 'shoulders', 'delts', '["trapezius","rhomboids","biceps"]', 'cable', 'strength', 'beginner', '["Attach a rope handle to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope handle with an overhand grip, palms facing each other.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Keep your elbows slightly bent and pull the rope towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["लो पुली केबल मशीन में रस्सी का हैंडल जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","रस्सी के हैंडल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ एक-दूसरे के सामने हों।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी कोहनियों को थोड़ा मोड़कर रखें और अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए रस्सी को अपनी छाती की ओर खींचें।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Cable_Rope_Rear-Delt_Rows/0.jpg","Cable_Rope_Rear-Delt_Rows/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0204', 'Cable Rear Drive', 'upper arms', 'triceps', '["shoulders","back"]', 'cable', 'strength', NULL, '["Attach a handle to a low pulley cable machine and stand facing away from the machine.","Grasp the handle with an overhand grip and extend your arms straight out in front of you.","Keeping your elbows stationary, pull the handle back towards your body, squeezing your triceps at the end of the movement.","Slowly return the handle to the starting position and repeat for the desired number of repetitions."]', '["लो पुली केबल मशीन में एक हैंडल जोड़ें और मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी बाहों को अपने सामने सीधा फैलाएं।","अपनी कोहनियों को स्थिर रखते हुए, आंदोलन के अंत में अपने ट्राइसेप्स को निचोड़ते हुए, हैंडल को अपने शरीर की ओर वापस खींचें।","धीरे-धीरे हैंडल को शुरुआती स्थिति में लौटाएं और वांछित संख्या में दोहराव के लिए दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0205', 'Cable Rear Pulldown', 'back', 'lats', '["biceps","rhomboids","rear deltoids"]', 'cable', 'strength', NULL, '["Adjust the cable machine so that the pulley is at the highest position.","Sit facing the machine with your feet flat on the ground and your knees slightly bent.","Grasp the cable attachment with an overhand grip, hands slightly wider than shoulder-width apart.","Lean back slightly, keeping your back straight and your chest up.","Pull the cable attachment down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the cable back up to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन को समायोजित करें ताकि चरखी उच्चतम स्थान पर हो।","अपने पैरों को ज़मीन पर सपाट करके और घुटनों को थोड़ा मोड़कर मशीन की ओर मुंह करके बैठें।","केबल अटैचमेंट को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी पीठ सीधी और छाती ऊपर रखते हुए थोड़ा पीछे झुकें।","अपने कंधे के ब्लेड को एक साथ दबाते हुए, केबल अटैचमेंट को अपनी छाती की ओर नीचे खींचें।","गति के निचले भाग पर एक पल के लिए रुकें, फिर धीरे-धीरे केबल को वापस प्रारंभिक स्थिति में छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0873', 'Cable Reverse Crunch', 'waist', 'abs', '["hip flexors"]', 'cable', 'strength', 'beginner', '["Attach a cable to a low pulley and lie down facing up on a mat.","Hold the cable with both hands and extend your arms straight up towards the ceiling.","Bend your knees and lift your legs up, bringing your thighs towards your chest.","While keeping your upper body stable, curl your pelvis up towards your chest, lifting your hips off the mat.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक केबल को निचली पुली से जोड़ें और एक चटाई पर ऊपर की ओर मुंह करके लेट जाएं।","केबल को दोनों हाथों से पकड़ें और अपनी भुजाओं को सीधे छत की ओर फैलाएँ।","अपने घुटनों को मोड़ें और अपने पैरों को ऊपर उठाएं, अपनी जांघों को अपनी छाती की ओर लाएं।","अपने ऊपरी शरीर को स्थिर रखते हुए, अपने कूल्हों को चटाई से ऊपर उठाते हुए, अपनी श्रोणि को अपनी छाती की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Cable_Reverse_Crunch/0.jpg","Cable_Reverse_Crunch/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0206', 'Cable Reverse Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', 'beginner', '["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["लो पुली केबल मशीन में एक सीधी पट्टी जोड़ें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर मशीन की ओर मुंह करके खड़े हो जाएं।","बार को अंडरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से अलग हों।","पूरे अभ्यास के दौरान अपनी कोहनियों को अपनी भुजाओं के पास और अपनी ऊपरी भुजाओं को स्थिर रखें।","सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए बार को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपनी बाहों को पूरी तरह फैलाते हुए बार को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Reverse_Cable_Curl/0.jpg","Reverse_Cable_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-2406', 'Cable Reverse Grip Triceps Pushdown (Sz-Bar) (With Arm Blaster)', 'upper arms', 'triceps', '["forearms"]', 'cable', 'strength', NULL, '["Attach a straight bar to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and slowly push the bar down until your arms are fully extended.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', '["उच्चतम सेटिंग पर केबल मशीन में एक सीधी पट्टी संलग्न करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","बार को अंडरहैंड ग्रिप से पकड़ें, हथेलियाँ ऊपर की ओर हों और आपके हाथ कंधे की चौड़ाई से अलग हों।","पूरे अभ्यास के दौरान अपनी कोहनियों को अपनी भुजाओं के पास और अपनी ऊपरी भुजाओं को स्थिर रखें।","अपने ट्राइसेप्स को संलग्न करें और धीरे-धीरे बार को तब तक नीचे धकेलें जब तक कि आपकी बाहें पूरी तरह विस्तारित न हो जाएं।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे बार को शुरुआती स्थिति में लौटा दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1413', 'Cable Reverse One Arm Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palm facing down.","Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","केबल के हैंडल को हाथ से पकड़ें, हथेली नीचे की ओर हो।","अपनी कोहनी को अपनी बगल में रखें और धीरे-धीरे अपने अग्रभाग को अपने कंधे की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी बांह को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0209', 'Cable Reverse Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Adjust the cable machine so that the preacher curl pad is at chest height.","Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended.","Grab the cable handles with an underhand grip, shoulder-width apart.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Repeat for the desired number of repetitions."]', '["केबल मशीन को समायोजित करें ताकि प्रीचर कर्ल पैड छाती की ऊंचाई पर हो।","प्रीचर कर्ल बेंच पर बैठें और अपनी ऊपरी भुजाओं को पैड पर रखें, आपकी हथेलियाँ नीचे की ओर हों और आपकी कोहनियाँ पूरी तरह फैली हुई हों।","केबल के हैंडल को कंधे की चौड़ाई की दूरी पर अंडरहैंड ग्रिप से पकड़ें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए हैंडल को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपनी कोहनियों को पूरी तरह फैलाते हुए हैंडल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0210', 'Cable Reverse Wrist Curl', 'lower arms', 'forearms', '["forearms","wrists"]', 'cable', 'strength', NULL, '["Attach a cable to a low pulley and sit on a bench facing the cable machine.","Grasp the cable handle with an overhand grip, palms facing down.","Rest your forearms on your thighs, with your wrists hanging off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक केबल को निचली पुली से जोड़ें और केबल मशीन के सामने एक बेंच पर बैठें।","केबल हैंडल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों।","अपनी कलाईयों को किनारे से लटकाते हुए अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ।","अपनी बांहों को स्थिर रखते हुए सांस छोड़ें और जहां तक ​​संभव हो अपनी कलाइयों को ऊपर की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे अपनी कलाइयों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0207', 'Cable Reverse-Grip Pushdown', 'upper arms', 'triceps', '["forearms"]', 'cable', 'strength', NULL, '["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Using your triceps, push the bar down until your arms are fully extended and your triceps are contracted.","Pause for a moment, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', '["हाई पुली केबल मशीन में एक सीधी पट्टी जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","बार को अंडरहैंड ग्रिप से पकड़ें, हथेलियाँ ऊपर की ओर हों और आपके हाथ कंधे की चौड़ाई से अलग हों।","पूरे अभ्यास के दौरान अपनी कोहनियों को अपनी भुजाओं के पास और अपनी ऊपरी भुजाओं को स्थिर रखें।","अपने ट्राइसेप्स का उपयोग करते हुए, बार को तब तक नीचे धकेलें जब तक कि आपकी बाहें पूरी तरह से विस्तारित न हो जाएं और आपके ट्राइसेप्स सिकुड़ न जाएं।","एक पल के लिए रुकें, फिर धीरे-धीरे बार को शुरुआती स्थिति में लौटा दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0208', 'Cable Reverse-Grip Straight Back Seated High Row', 'back', 'upper back', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Sit on the seat facing the cable machine with your feet flat on the floor.","Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your back straight and lean slightly forward from your hips.","Pull the cable towards your torso by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फर्श पर सपाट करके केबल मशीन के सामने वाली सीट पर बैठें।","केबल अटैचमेंट को अंडरहैंड ग्रिप से पकड़ें, हथेलियाँ ऊपर की ओर हों और आपके हाथ कंधे की चौड़ाई से अलग हों।","अपनी पीठ सीधी रखें और अपने कूल्हों से थोड़ा आगे की ओर झुकें।","अपने कंधे के ब्लेड को पीछे खींचकर और अपनी पीठ की मांसपेशियों को निचोड़कर केबल को अपने धड़ की ओर खींचें।","संकुचन के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे केबल को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1320', 'Cable Rope Crossover Seated Row', 'back', 'upper back', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent.","Grasp the cable ropes with an overhand grip, palms facing each other.","Lean back slightly, keeping your back straight and your core engaged.","Pull the cable ropes towards your chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फुटरेस्ट पर सपाट करके और अपने घुटनों को थोड़ा मोड़कर रोइंग मशीन पर बैठें।","केबल रस्सियों को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ एक-दूसरे के सामने हों।","अपनी पीठ सीधी और अपने कोर को व्यस्त रखते हुए थोड़ा पीछे झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, केबल रस्सियों को अपनी छाती की ओर खींचें।","गति के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1321', 'Cable Rope Elevated Seated Row', 'back', 'upper back', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Sit on the elevated seat facing the cable machine.","Grab the cable rope handles with an overhand grip, palms facing each other.","Keep your back straight and lean slightly back, maintaining a slight bend in your knees.","Pull the cable towards your body by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the fully contracted position.","Slowly release the tension and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन की ओर मुंह करके ऊंची सीट पर बैठें।","केबल रस्सी के हैंडल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ एक-दूसरे के सामने हों।","अपनी पीठ सीधी रखें और अपने घुटनों को थोड़ा मोड़ते हुए थोड़ा पीछे झुकें।","अपने कंधे के ब्लेड को पीछे खींचकर और अपनी पीठ की मांसपेशियों को निचोड़कर केबल को अपने शरीर की ओर खींचें।","पूरी तरह से अनुबंधित स्थिति पर एक पल के लिए रुकें।","धीरे-धीरे तनाव छोड़ें और अपनी भुजाओं को वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1322', 'Cable Rope Extension Incline Bench Row', 'back', 'upper back', '["biceps","shoulders"]', 'cable', 'strength', NULL, '["Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley.","Attach a rope handle to the cable machine and sit on the incline bench facing the machine.","Grab the rope handle with an overhand grip and lean forward, keeping your back straight.","Extend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body.","Squeeze your shoulder blades together at the end of the movement.","Slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["45-डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें और एक केबल मशीन को निचली चरखी से जोड़ दें।","केबल मशीन में एक रस्सी का हैंडल जोड़ें और मशीन के सामने झुकी हुई बेंच पर बैठें।","रस्सी के हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी पीठ सीधी रखते हुए आगे की ओर झुकें।","अपनी बाहों को पूरी तरह फैलाएं, अपनी कोहनियों को अपने शरीर के करीब रखते हुए रस्सी को अपनी ऊपरी छाती की ओर खींचें।","आंदोलन के अंत में अपने कंधे के ब्लेड को एक साथ निचोड़ें।","धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1639', 'Cable Rope Hammer Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Attach a rope attachment to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with a neutral grip (palms facing each other).","Position your upper arms against the preacher bench pad, keeping your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the rope back to the starting position.","Repeat for the desired number of repetitions."]', '["एक लो पुली केबल मशीन में रस्सी का अटैचमेंट जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","रस्सी को तटस्थ पकड़ से पकड़ें (हथेलियाँ एक दूसरे के सामने)।","अपनी कोहनियों को थोड़ा मुड़ा हुआ रखते हुए, अपनी ऊपरी भुजाओं को उपदेशक बेंच पैड के सामने रखें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़कर रस्सी को अपने कंधों की ओर मोड़ें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे रस्सी को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1724', 'Cable Rope High Pulley Overhead Tricep Extension', 'upper arms', 'triceps', '["shoulders"]', 'cable', 'strength', NULL, '["Attach a rope to a high pulley and adjust the weight accordingly.","Stand facing away from the pulley machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing down, and bring your hands above your head.","Keep your upper arms close to your head and perpendicular to the floor.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["एक ऊंची चरखी में एक रस्सी जोड़ें और उसके अनुसार वजन समायोजित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए पुली मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","दोनों हाथों से रस्सी को पकड़ें, हथेलियाँ नीचे की ओर हों और अपने हाथों को अपने सिर के ऊपर ले आएँ।","अपनी ऊपरी भुजाओं को अपने सिर के पास और फर्श से लंबवत रखें।","अपनी कोहनियों को मोड़कर धीरे-धीरे रस्सी को अपने सिर के पीछे नीचे लाएँ।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1725', 'Cable Rope Incline Tricep Extension', 'upper arms', 'triceps', '["shoulders"]', 'cable', 'strength', NULL, '["Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.","Stand facing away from the pulley with your feet shoulder-width apart.","Grasp the rope with an overhand grip and extend your arms straight overhead.","Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Lower the rope behind your head by bending your elbows until your forearms touch your biceps.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["एक ऊँची चरखी में एक रस्सी जोड़ें और झुकी हुई बेंच को एक आरामदायक कोण पर समायोजित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए चरखी से दूर की ओर मुंह करके खड़े हो जाएं।","रस्सी को ऊपरी पकड़ से पकड़ें और अपनी भुजाओं को सीधा ऊपर की ओर फैलाएँ।","पूरे अभ्यास के दौरान अपनी कोहनियों को अपने सिर के पास और अपनी ऊपरी भुजाओं को स्थिर रखें।","अपनी कोहनियों को मोड़कर रस्सी को अपने सिर के पीछे तब तक नीचे करें जब तक कि आपके अग्रबाहु आपके बाइसेप्स को न छू लें।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1726', 'Cable Rope Lying On Floor Tricep Extension', 'upper arms', 'triceps', '["shoulders"]', 'cable', 'strength', NULL, '["Attach a rope to a cable machine and set it to the lowest position.","Lie on the floor facing up, with your head towards the cable machine.","Hold the rope with both hands, palms facing each other, and extend your arms straight up towards the ceiling.","Keep your upper arms stationary and slowly lower the rope towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन में एक रस्सी जोड़ें और इसे सबसे निचले स्थान पर सेट करें।","फर्श पर ऊपर की ओर मुंह करके लेटें, अपना सिर केबल मशीन की ओर रखें।","रस्सी को दोनों हाथों से पकड़ें, हथेलियाँ एक-दूसरे के सामने हों, और अपनी भुजाओं को छत की ओर सीधा ऊपर फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखें और अपनी कोहनियों को मोड़ते हुए धीरे-धीरे रस्सी को अपने माथे की ओर नीचे करें।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1640', 'Cable Rope One Arm Hammer Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Attach a rope handle to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope handle with an underhand grip, palms facing up.","Position your upper arm against the preacher bench pad, keeping your elbow slightly bent.","Keep your back straight and your core engaged throughout the exercise.","Slowly curl the rope handle towards your shoulder, keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the rope handle back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["लो पुली केबल मशीन में रस्सी का हैंडल जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","रस्सी के हैंडल को हाथ से पकड़ें, हथेलियाँ ऊपर की ओर हों।","अपनी ऊपरी भुजा को उपदेशक बेंच पैड के सामने रखें, अपनी कोहनी को थोड़ा मोड़कर रखें।","पूरे अभ्यास के दौरान अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपने ऊपरी बांह को स्थिर रखते हुए धीरे-धीरे रस्सी के हैंडल को अपने कंधे की ओर मोड़ें।","आंदोलन के शीर्ष पर अपने बाइसेप्स को निचोड़ें, फिर धीरे-धीरे रस्सी के हैंडल को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1323', 'Cable Rope Seated Row', 'back', 'upper back', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Sit on the rowing machine with your feet flat on the footrests and knees slightly bent.","Grasp the cable ropes with an overhand grip, palms facing each other.","Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Pull the cable ropes towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फुटरेस्ट पर सपाट करके और घुटनों को थोड़ा मोड़कर रोइंग मशीन पर बैठें।","केबल रस्सियों को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ एक-दूसरे के सामने हों।","अपनी पीठ सीधी रखें और अपनी कोहनियों को हल्का सा मोड़ते हुए थोड़ा आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, केबल रस्सियों को अपने शरीर की ओर खींचें।","गति के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0211', 'Cable Russian Twists (On Stability Ball)', 'waist', 'abs', '["obliques","lower back"]', 'cable', 'strength', NULL, '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold the cable handle with both hands and extend your arms straight out in front of you.","Lean back slightly while keeping your back straight and your core engaged.","Twist your torso to the right, bringing the cable handle towards your right hip.","Pause for a moment, then twist your torso to the left, bringing the cable handle towards your left hip.","Continue alternating twists for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को 90 डिग्री के कोण पर मोड़कर एक स्टेबिलिटी बॉल पर बैठें।","केबल के हैंडल को दोनों हाथों से पकड़ें और अपनी बाहों को अपने सामने सीधा फैलाएं।","अपनी पीठ सीधी और अपने कोर को व्यस्त रखते हुए थोड़ा पीछे झुकें।","अपने धड़ को दाईं ओर मोड़ें, केबल के हैंडल को अपने दाहिने कूल्हे की ओर लाएं।","एक पल के लिए रुकें, फिर अपने धड़ को बाईं ओर मोड़ें, केबल के हैंडल को अपने बाएं कूल्हे की ओर लाएं।","पुनरावृत्ति की वांछित संख्या के लिए बारी-बारी से मोड़ जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2144', 'Cable Seated Chest Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'cable', 'strength', NULL, '["Adjust the seat height and cable handles to a comfortable position.","Sit on the bench with your back straight and feet flat on the floor.","Grasp the cable handles with an overhand grip at shoulder height.","Push the handles forward and away from your body, extending your arms fully.","Pause for a moment, then slowly bring the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["सीट की ऊंचाई और केबल हैंडल को आरामदायक स्थिति में समायोजित करें।","अपनी पीठ सीधी और पैर फर्श पर सपाट करके बेंच पर बैठें।","केबल के हैंडल को कंधे की ऊंचाई पर ओवरहैंड ग्रिप से पकड़ें।","अपनी भुजाओं को पूरी तरह फैलाते हुए, हैंडल को अपने शरीर से आगे और दूर धकेलें।","एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0212', 'Cable Seated Crunch', 'waist', 'abs', '["obliques"]', 'cable', 'strength', 'beginner', '["Sit on a cable machine with your feet flat on the ground and your knees bent.","Hold the cable handle with both hands and position it behind your head.","Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को मोड़कर एक केबल मशीन पर बैठें।","केबल के हैंडल को दोनों हाथों से पकड़ें और इसे अपने सिर के पीछे रखें।","अपने पेट को संलग्न करें और धीरे-धीरे अपने ऊपरी शरीर को आगे की ओर मोड़ें, अपनी छाती को अपने घुटनों की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Cable_Seated_Crunch/0.jpg","Cable_Seated_Crunch/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1641', 'Cable Seated Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Sit on a cable machine with your feet flat on the ground and your back straight.","Grasp the cable attachment with an underhand grip, palms facing up, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा करके एक केबल मशीन पर बैठें।","केबल अटैचमेंट को अंडरहैंड ग्रिप से पकड़ें, हथेलियाँ ऊपर की ओर हों और आपकी भुजाएँ पूरी तरह फैली हुई हों।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए केबल अटैचमेंट को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपनी बाहों को पूरी तरह फैलाते हुए केबल अटैचमेंट को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0213', 'Cable Seated High Row (V-Bar)', 'back', 'lats', '["biceps","rhomboids","rear deltoids"]', 'cable', 'strength', NULL, '["Sit on the cable machine with your feet flat on the floor and your knees slightly bent.","Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart.","Keep your back straight and lean slightly forward from the hips.","Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फर्श पर सपाट करके और अपने घुटनों को थोड़ा मोड़कर केबल मशीन पर बैठें।","वी-बार अटैचमेंट को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ एक-दूसरे के सामने हों और आपके हाथ कंधे की चौड़ाई से अलग हों।","अपनी पीठ सीधी रखें और कूल्हों से थोड़ा आगे की ओर झुकें।","अपने कंधे के ब्लेड को पीछे खींचकर और अपनी पीठ की मांसपेशियों को निचोड़कर वी-बार को अपने धड़ की ओर खींचें।","संकुचन के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0214', 'Cable Seated One Arm Alternate Row', 'back', 'upper back', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent.","Grasp the handle with one hand and keep your arm fully extended in front of you.","Pull the handle towards your body, retracting your shoulder blade and keeping your elbow close to your side.","Pause for a moment at the top of the movement, squeezing your back muscles.","Slowly release the handle back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट और घुटनों को थोड़ा मोड़कर केबल मशीन के सामने एक बेंच पर बैठें।","एक हाथ से हैंडल को पकड़ें और अपने हाथ को अपने सामने पूरी तरह फैलाकर रखें।","अपने कंधे के ब्लेड को पीछे खींचते हुए और अपनी कोहनी को अपनी तरफ रखते हुए, हैंडल को अपने शरीर की ओर खींचें।","अपनी पीठ की मांसपेशियों को निचोड़ते हुए, आंदोलन के शीर्ष पर एक पल के लिए रुकें।","धीरे-धीरे हैंडल को वापस प्रारंभिक स्थिति में छोड़ें।","दूसरे हाथ से दोहराएँ.","दोहराव की वांछित संख्या के लिए भुजाओं के बीच वैकल्पिक करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1642', 'Cable Seated One Arm Concentration Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Sit on a bench with your feet flat on the floor and your back straight.","Hold a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee.","Keep your upper arm stationary and curl the cable handle towards your shoulder while exhaling.","Pause for a moment at the top of the movement, squeezing your biceps.","Slowly lower the cable handle back to the starting position while inhaling.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को फर्श पर सपाट और अपनी पीठ को सीधा करके एक बेंच पर बैठें।","एक हाथ से केबल के हैंडल को पकड़ें और अपनी कोहनी को अपनी जांघ के अंदर, घुटने के ठीक ऊपर रखें।","अपनी ऊपरी बांह को स्थिर रखें और सांस छोड़ते हुए केबल के हैंडल को अपने कंधे की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","सांस लेते हुए धीरे-धीरे केबल हैंडल को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1643', 'Cable Seated Overhead Curl', 'upper arms', 'biceps', '["forearms","shoulders"]', 'cable', 'strength', NULL, '["Sit on a bench facing the cable machine with your feet flat on the ground.","Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your upper arms stationary and your elbows close to your sides.","Exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके केबल मशीन के सामने एक बेंच पर बैठें।","केबल अटैचमेंट को अंडरहैंड ग्रिप से पकड़ें, हथेलियाँ ऊपर की ओर हों और आपके हाथ कंधे की चौड़ाई से अलग हों।","अपनी ऊपरी भुजाओं को स्थिर रखें और अपनी कोहनियों को अपनी भुजाओं के पास रखें।","सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए केबल अटैचमेंट को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपनी बाहों को पूरी तरह फैलाते हुए केबल अटैचमेंट को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0215', 'Cable Seated Rear Lateral Raise', 'shoulders', 'delts', '["traps","rhomboids"]', 'cable', 'strength', NULL, '["Sit on a bench facing the cable machine with your feet flat on the ground.","Grasp the cable handles with an overhand grip and extend your arms straight in front of you.","Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके केबल मशीन के सामने एक बेंच पर बैठें।","केबल के हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी बाहों को अपने सामने सीधा फैलाएं।","अपनी भुजाओं को सीधा रखते हुए, धीरे-धीरे उन्हें बगल की ओर उठाएं जब तक कि वे फर्श के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0861', 'Cable Seated Row', 'back', 'upper back', '["biceps","forearms"]', 'cable', 'strength', 'beginner', '["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with an overhand grip, keeping your back straight and your shoulders relaxed.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["केबल रो मशीन पर अपने पैरों को फ़ुटरेस्ट पर सपाट करके और अपने घुटनों को थोड़ा मोड़कर बैठें।","अपनी पीठ को सीधा रखते हुए और अपने कंधों को आराम से रखते हुए, हैंडल को ओवरहैंड ग्रिप से पकड़ें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपने शरीर की ओर खींचें।","गति के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Seated_Cable_Rows/0.jpg","Seated_Cable_Rows/1.jpg"]', 5, 'sets', 1, 'opengym', 1),
('og-0216', 'Cable Seated Shoulder Internal Rotation', 'shoulders', 'delts', '["rotator cuff","triceps"]', 'cable', 'strength', NULL, '["Sit on a bench or chair facing the cable machine with your feet flat on the ground.","Hold the cable handle with your arm extended straight out in front of you, parallel to the ground.","Keep your elbow slightly bent and your shoulder blades pulled back and down.","Slowly rotate your arm inward, bringing the cable handle towards the center of your body.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को ज़मीन पर सपाट करके केबल मशीन के सामने एक बेंच या कुर्सी पर बैठें।","केबल के हैंडल को अपने हाथ को जमीन के समानांतर अपने सामने सीधा फैलाकर पकड़ें।","अपनी कोहनी को थोड़ा मोड़कर रखें और अपने कंधे के ब्लेड को पीछे और नीचे की ओर खींचें।","धीरे-धीरे अपने हाथ को अंदर की ओर घुमाएं, केबल के हैंडल को अपने शरीर के केंद्र की ओर लाएं।","आंदोलन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2399', 'Cable Seated Twist', 'waist', 'abs', '["obliques"]', 'cable', 'strength', NULL, '["Sit on a cable machine with your feet flat on the ground and your knees slightly bent.","Hold the cable handle with both hands and extend your arms straight in front of you.","Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body.","Pause for a moment at the end of the range of motion, then slowly rotate back to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को थोड़ा मोड़कर एक केबल मशीन पर बैठें।","केबल के हैंडल को दोनों हाथों से पकड़ें और अपनी बाहों को अपने सामने सीधा फैलाएं।","अपने कोर को व्यस्त रखते हुए, धीरे-धीरे अपने धड़ को एक तरफ घुमाएं, केबल को अपने शरीर पर खींचें।","गति की सीमा के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में वापस आएँ।","दूसरी तरफ दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0218', 'Cable Seated Wide-Grip Row', 'back', 'upper back', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handle with a wide overhand grip, palms facing down.","Keep your back straight and lean slightly forward from the hips.","Pull the handle towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the contraction.","Slowly release the handle back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["केबल रो मशीन पर अपने पैरों को फ़ुटरेस्ट पर सपाट करके और अपने घुटनों को थोड़ा मोड़कर बैठें।","हैंडल को चौड़ी ओवरहैंड पकड़ से पकड़ें, हथेलियाँ नीचे की ओर हों।","अपनी पीठ सीधी रखें और कूल्हों से थोड़ा आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपनी निचली छाती की ओर खींचें।","संकुचन के चरम पर एक क्षण के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए धीरे-धीरे हैंडल को वापस प्रारंभिक स्थिति में छोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0219', 'Cable Shoulder Press', 'shoulders', 'delts', '["triceps","upper back"]', 'cable', 'strength', 'beginner', '["Adjust the cable machine so that the handles are at shoulder height.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards.","Press the handles upwards until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the handles back down to shoulder level.","Repeat for the desired number of repetitions."]', '["केबल मशीन को समायोजित करें ताकि हैंडल कंधे की ऊंचाई पर हों।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी कोहनियों को मोड़कर बाहर की ओर रखते हुए उन्हें कंधे के स्तर तक ले आएं।","हैंडल को ऊपर की ओर तब तक दबाएं जब तक कि आपकी भुजाएं पूरी तरह से ऊपर की ओर न फैल जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को वापस कंधे के स्तर तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Alternating_Cable_Shoulder_Press/0.jpg","Alternating_Cable_Shoulder_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0220', 'Cable Shrug', 'back', 'traps', '["shoulders"]', 'cable', 'strength', 'beginner', '["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handles with an overhand grip and let your arms hang down in front of you.","Keeping your arms straight, shrug your shoulders up towards your ears.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","केबल के हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी भुजाओं को अपने सामने नीचे लटका दें।","अपनी भुजाओं को सीधा रखते हुए, अपने कंधों को अपने कानों की ओर ऊपर उठाएं।","एक क्षण के लिए संकुचन को रोककर रखें, फिर धीरे-धीरे अपने कंधों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Cable_Shrugs/0.jpg","Cable_Shrugs/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0222', 'Cable Side Bend', 'waist', 'abs', '["obliques"]', 'cable', 'strength', NULL, '["Stand with your feet shoulder-width apart and grasp the cable handle with one hand.","Keep your back straight and your core engaged.","Slowly bend sideways at the waist, lowering the cable handle towards your knee.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Alternate sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ से केबल के हैंडल को पकड़ लें।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","धीरे-धीरे कमर के बल बग़ल में झुकें, केबल के हैंडल को अपने घुटने की ओर नीचे करें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौट आएं।","दूसरी तरफ दोहराएं।","दोहराव की वांछित संख्या के लिए वैकल्पिक पक्ष।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0221', 'Cable Side Bend Crunch (Bosu Ball)', 'waist', 'abs', '["obliques"]', 'cable', 'strength', 'beginner', '["Stand with your feet shoulder-width apart, holding a cable handle in one hand.","Place the other hand on your hip.","Engage your core and slowly bend sideways towards the hand holding the cable, keeping your back straight.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े रहें, एक हाथ में केबल का हैंडल पकड़ें।","दूसरे हाथ को अपने कूल्हे पर रखें।","अपने कोर को संलग्न करें और धीरे-धीरे अपनी पीठ को सीधा रखते हुए, केबल को पकड़ने वाले हाथ की ओर बग़ल में झुकें।","गति के निचले भाग पर एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', '["Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg","Bosu_Ball_Cable_Crunch_With_Side_Bends/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0223', 'Cable Side Crunch', 'waist', 'abs', '["obliques"]', 'cable', 'strength', NULL, '["Attach a cable handle to a low pulley and stand sideways to the machine.","Grasp the handle with the hand furthest from the machine and place your other hand on your hip.","Keep your feet shoulder-width apart and your knees slightly bent.","With your abs engaged, bend sideways at the waist, bringing your elbow down towards your hip.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["एक केबल हैंडल को निचली चरखी से जोड़ें और मशीन के किनारे खड़े हो जाएं।","मशीन से सबसे दूर वाले हाथ से हैंडल को पकड़ें और अपने दूसरे हाथ को अपने कूल्हे पर रखें।","अपने पैरों को कंधे की चौड़ाई से अलग रखें और आपके घुटने थोड़े मुड़े हुए हों।","अपने पेट को व्यस्त रखते हुए, कमर के बल बग़ल में झुकें, अपनी कोहनी को अपने कूल्हे की ओर नीचे लाएँ।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1717', 'Cable Squat Row (With Rope Attachment)', 'back', 'lats', '["biceps","rhomboids","rear deltoids"]', 'cable', 'strength', NULL, '["Attach a rope to a cable machine at waist height.","Stand facing the cable machine with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position, keeping your back straight and chest up.","Grasp the rope with an overhand grip, with your hands shoulder-width apart.","Engage your core and pull the rope towards your body, squeezing your shoulder blades together.","Keep your elbows close to your body and continue pulling until your hands reach your chest.","Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन में कमर की ऊंचाई पर एक रस्सी जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","अपने घुटनों को मोड़ें और अपने शरीर को स्क्वाट स्थिति में लाएँ, अपनी पीठ सीधी और छाती ऊपर रखें।","अपने हाथों को कंधे की चौड़ाई से अलग रखते हुए, रस्सी को ओवरहैंड ग्रिप से पकड़ें।","अपने कोर को संलग्न करें और अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए रस्सी को अपने शरीर की ओर खींचें।","अपनी कोहनियों को अपने शरीर के पास रखें और तब तक खींचते रहें जब तक आपके हाथ आपकी छाती तक न पहुंच जाएं।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे रस्सी को छोड़ें और अपनी भुजाओं को वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1644', 'Cable Squatting Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Attach a cable handle to the lowest setting on a cable machine.","Stand facing the machine with your feet shoulder-width apart.","Hold the cable handle with an underhand grip, palms facing up, and arms fully extended.","Lower your body into a squat position, keeping your back straight and knees behind your toes.","As you squat down, curl the cable handle towards your shoulders, keeping your elbows close to your sides.","Pause for a moment at the top of the curl, squeezing your biceps.","Slowly lower the cable handle back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["केबल मशीन पर सबसे निचली सेटिंग पर केबल हैंडल संलग्न करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","केबल के हैंडल को अंडरहैंड ग्रिप से पकड़ें, हथेलियाँ ऊपर की ओर हों और बाहें पूरी तरह फैली हुई हों।","अपने शरीर को स्क्वाट स्थिति में लाएँ, अपनी पीठ को सीधा रखें और घुटनों को अपने पैर की उंगलियों के पीछे रखें।","जैसे ही आप बैठते हैं, केबल के हैंडल को अपने कंधों की ओर मोड़ें, अपनी कोहनियों को अपने किनारों के करीब रखें।","अपने बाइसेप्स को निचोड़ते हुए, कर्ल के शीर्ष पर एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए धीरे-धीरे केबल हैंडल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0224', 'Cable Standing Back Wrist Curl', 'lower arms', 'forearms', '["biceps","brachialis"]', 'cable', 'strength', NULL, '["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable handle with an overhand grip, palms facing down.","Keep your arms straight and your elbows close to your sides.","Slowly curl your wrists upward, bringing the cable handle towards your body.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","केबल के हैंडल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों।","अपनी भुजाओं को सीधा रखें और अपनी कोहनियों को अपनी भुजाओं के पास रखें।","धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, केबल के हैंडल को अपने शरीर की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे केबल हैंडल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1375', 'Cable Standing Calf Raise', 'lower legs', 'calves', '["hamstrings","glutes"]', 'cable', 'strength', NULL, '["Stand facing a cable machine with your feet shoulder-width apart.","Hold onto the cable machine handles or attach a cable ankle strap to your ankles.","Raise your heels off the ground by extending your ankles as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","केबल मशीन के हैंडल को पकड़ें या अपनी एड़ियों पर केबल टखने का पट्टा लगाएँ।","जितना संभव हो सके अपनी एड़ियों को फैलाकर अपनी एड़ियों को जमीन से ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0225', 'Cable Standing Cross-Over High Reverse Fly', 'shoulders', 'delts', '["trapezius","rhomboids","rear deltoids"]', 'cable', 'strength', NULL, '["Attach a D-handle to each side of a cable machine at shoulder height.","Stand in the middle of the cable machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and extend your arms out to the sides, palms facing forward.","Keep a slight bend in your elbows and maintain a straight back throughout the exercise.","Engage your shoulder muscles and squeeze your shoulder blades together as you pull the handles towards the front of your body.","Pause for a moment at the peak of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन के प्रत्येक तरफ कंधे की ऊंचाई पर एक डी-हैंडल संलग्न करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन के बीच में खड़े हो जाएं।","हैंडल को ओवरहैंड ग्रिप से पकड़ें और अपनी भुजाओं को बगल की ओर फैलाएं, हथेलियाँ आगे की ओर हों।","अपनी कोहनियों को थोड़ा मोड़ें और पूरे अभ्यास के दौरान अपनी पीठ सीधी रखें।","अपने कंधे की मांसपेशियों को संलग्न करें और हैंडल को अपने शरीर के सामने की ओर खींचते हुए अपने कंधे के ब्लेड को एक साथ निचोड़ें।","गति के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0226', 'Cable Standing Crunch', 'waist', 'abs', '["obliques"]', 'cable', 'strength', NULL, '["Attach a cable handle to a high pulley and stand facing away from the machine.","Hold the handle with both hands and place it behind your head, keeping your elbows bent.","Stand with your feet shoulder-width apart and your knees slightly bent.","Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["एक केबल हैंडल को एक ऊंची पुली से जोड़ें और मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","हैंडल को दोनों हाथों से पकड़ें और अपनी कोहनियों को मोड़ते हुए इसे अपने सिर के पीछे रखें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","अपने पेट को व्यस्त रखते हुए, सांस छोड़ें और अपने धड़ को घुटनों की ओर झुकाएं, अपनी कोहनियों को अपनी जांघों की ओर लाएं।","गति के निचले भाग पर एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0874', 'Cable Standing Crunch (With Rope Attachment)', 'waist', 'abs', '["obliques"]', 'cable', 'strength', NULL, '["Attach a rope to a cable machine at chest height.","Stand facing away from the machine with your feet shoulder-width apart.","Hold the rope with both hands and bring it behind your head, keeping your elbows bent.","Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees.","Pause for a moment at the top of the crunch, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन में छाती की ऊंचाई पर एक रस्सी जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","रस्सी को दोनों हाथों से पकड़ें और अपनी कोहनियों को मोड़ते हुए इसे अपने सिर के पीछे ले आएं।","अपने पेट को संलग्न करें और धीरे-धीरे अपने धड़ को आगे की ओर झुकाएं, अपनी कोहनियों को अपने घुटनों की ओर लाएं।","क्रंच के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0227', 'Cable Standing Fly', 'chest', 'pectorals', '["deltoids","triceps"]', 'cable', 'strength', NULL, '["Attach the handles to the cables at chest height.","Stand with your feet shoulder-width apart, facing away from the cable machine.","Grasp the handles with an overhand grip, palms facing forward.","Step forward slightly to create tension in the cables.","Keep your core engaged and your back straight throughout the exercise.","With a slight bend in your elbows, slowly bring your arms forward and together in front of your chest.","Squeeze your chest muscles at the peak of the movement.","Slowly reverse the movement, returning your arms to the starting position.","Repeat for the desired number of repetitions."]', '["हैंडल को केबल से छाती की ऊंचाई पर जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग करके, केबल मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","हैंडल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ आगे की ओर हों।","केबलों में तनाव पैदा करने के लिए थोड़ा आगे बढ़ें।","पूरे अभ्यास के दौरान अपने कोर को व्यस्त रखें और अपनी पीठ को सीधा रखें।","अपनी कोहनियों को थोड़ा मोड़कर, धीरे-धीरे अपनी भुजाओं को आगे और एक साथ अपनी छाती के सामने लाएँ।","आंदोलन के चरम पर अपनी छाती की मांसपेशियों को निचोड़ें।","धीरे-धीरे गति को उल्टा करें, अपनी भुजाओं को प्रारंभिक स्थिति में लौटाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0228', 'Cable Standing Hip Extension', 'upper legs', 'glutes', '["hamstrings","quadriceps"]', 'cable', 'strength', NULL, '["Attach a cable to a low pulley and stand facing away from the machine.","Place the cable around your ankle and stand with your feet shoulder-width apart.","Keep your core engaged and your back straight throughout the exercise.","Slowly extend your leg straight back, squeezing your glutes at the top of the movement.","Pause for a moment, then return to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat with the other leg."]', '["एक केबल को निचली पुली से जोड़ें और मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","केबल को अपने टखने के चारों ओर रखें और अपने पैरों को कंधे की चौड़ाई से अलग करके खड़े हो जाएं।","पूरे अभ्यास के दौरान अपने कोर को व्यस्त रखें और अपनी पीठ को सीधा रखें।","धीरे-धीरे अपने पैर को सीधे पीछे की ओर बढ़ाएं, आंदोलन के शीर्ष पर अपने ग्लूट्स को निचोड़ें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।","किनारे बदलें और दूसरे पैर से दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0229', 'Cable Standing Inner Curl', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palms facing up.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the cable handle towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","केबल के हैंडल को अंडरहैंड ग्रिप से पकड़ें, हथेलियाँ ऊपर की ओर।","अपनी कोहनियों को अपनी भुजाओं के पास रखें और अपनी ऊपरी भुजाओं को स्थिर रखें।","सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए केबल हैंडल को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे केबल हैंडल को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0230', 'Cable Standing Lift', 'waist', 'abs', '["obliques","lower back"]', 'cable', 'strength', 'beginner', '["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with both hands and position it at waist height.","Engage your core and maintain a straight back throughout the exercise.","Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso.","Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","केबल के हैंडल को दोनों हाथों से पकड़ें और इसे कमर की ऊंचाई पर रखें।","अपने कोर को व्यस्त रखें और पूरे अभ्यास के दौरान अपनी पीठ सीधी रखें।","अपनी बाहों को सीधा रखते हुए, सांस छोड़ें और अपने धड़ को घुमाते हुए केबल के हैंडल को अपने विपरीत कंधे की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे केबल हैंडल को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', '["Standing_Cable_Lift/0.jpg","Standing_Cable_Lift/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0231', 'Cable Standing One Arm Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'cable', 'strength', NULL, '["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground.","Keep your elbow stationary and close to your body.","Slowly bend your elbow, lowering the cable handle towards the back of your head.","Pause for a moment at the bottom of the movement, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm."]', '["केबल मशीन की ओर मुंह करके अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं।","केबल के हैंडल को अपने दाहिने हाथ से पकड़ें, हथेली नीचे की ओर हो, और अपने हाथ को इस तरह रखें कि वह पूरी तरह फैला हुआ हो और जमीन के समानांतर हो।","अपनी कोहनी को स्थिर और अपने शरीर के पास रखें।","धीरे-धीरे अपनी कोहनी मोड़ें, केबल के हैंडल को अपने सिर के पीछे की ओर नीचे करें।","गति के निचले भाग में एक पल के लिए रुकें, फिर अपने हाथ को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें और अपने बाएं हाथ से व्यायाम करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1376', 'Cable Standing One Leg Calf Raise', 'lower legs', 'calves', '["ankles","feet"]', 'cable', 'strength', NULL, '["Stand facing a cable machine with your feet shoulder-width apart.","Hold onto the cable machine for support.","Lift one leg off the ground and balance on the other leg.","Slowly raise your heel off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","समर्थन के लिए केबल मशीन को पकड़ें।","एक पैर को जमीन से ऊपर उठाएं और दूसरे पैर पर संतुलन बनाएं।","धीरे-धीरे अपनी एड़ी को जमीन से ऊपर उठाएं, अपने शरीर को अपने पैर की उंगलियों पर ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ी को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0232', 'Cable Standing Pulldown (With Rope)', 'upper arms', 'biceps', '["forearms","shoulders"]', 'cable', 'strength', NULL, '["Attach a rope to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing down.","Keep your back straight and core engaged throughout the exercise.","Pull the rope down towards your thighs, squeezing your biceps.","Pause for a moment at the bottom, then slowly release the rope back up.","Repeat for the desired number of repetitions."]', '["उच्चतम सेटिंग पर केबल मशीन में एक रस्सी जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","रस्सी को हाथ से पकड़ें, हथेलियाँ नीचे की ओर हों।","पूरे अभ्यास के दौरान अपनी पीठ सीधी रखें और मुख्य भाग को व्यस्त रखें।","अपने बाइसेप्स को सिकोड़ते हुए रस्सी को अपनी जाँघों की ओर नीचे खींचें।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे रस्सी को वापस ऊपर छोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0233', 'Cable Standing Rear Delt Row (With Rope)', 'shoulders', 'delts', '["trapezius","rhomboids","biceps"]', 'cable', 'strength', NULL, '["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable.","Keep your back straight and your core engaged.","Pull the cable towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","केबल अटैचमेंट को दोनों हाथों से पकड़ें, हथेलियाँ एक-दूसरे के सामने हों, और केबल में तनाव पैदा करने के लिए पीछे हटें।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, केबल को अपने शरीर की ओर खींचें।","गति के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे केबल को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
